function QrScannerModal({ onDetected, onClose }: { onDetected: (value: string) => void; onClose: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const [message,setMessage]=useState("カメラを起動しています…");
  useEffect(()=>{let stream:MediaStream|undefined;let timer:number|undefined;let closed=false;const boot=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error("CAMERA_UNAVAILABLE");stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});if(closed){stream.getTracks().forEach(track=>track.stop());return;}if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play();}const Detector=(window as Window & { BarcodeDetector?: new (options:{formats:string[]})=>{detect:(source:unknown)=>Promise<Array<{rawValue?:string}>>} }).BarcodeDetector;if(!Detector){setMessage("このブラウザはQRの自動読取に対応していません。教室コードを手入力してください。");return;}const detector=new Detector({formats:["qr_code"]});setMessage("QRコードを枠内に写してください。");timer=window.setInterval(async()=>{if(!videoRef.current)return;try{const found=await detector.detect(videoRef.current);const raw=found[0]?.rawValue?.trim();if(raw){const code=raw.replace(/^STUDYVERSE:/i,"").trim();onDetected(code);}}catch{/* フレーム読取失敗時は次の周期で再試行 */}},450);}catch(error){setMessage(error instanceof DOMException&&error.name==="NotAllowedError"?"カメラの利用が許可されませんでした。教室コードを手入力してください。":"カメラを開始できませんでした。教室コードを手入力してください。");}};void boot();return()=>{closed=true;if(timer)window.clearInterval(timer);stream?.getTracks().forEach(track=>track.stop());};},[onDetected]);
  return <div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/80 p-4 sm:place-items-center"><section className="glass-card w-full max-w-md rounded-[28px] p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">qr classroom code</p><h2 className="mt-1 text-lg font-bold">教室コードを読み取る</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8" aria-label="閉じる"><X className="h-4 w-4"/></button></div><div className="mt-5 overflow-hidden rounded-2xl border border-cyan-200/20 bg-slate-950/45"><video ref={videoRef} muted playsInline className="aspect-video w-full object-cover"/><div className="relative -mt-[55%] mx-auto h-40 w-40 rounded-2xl border-2 border-cyan-200/80 shadow-[0_0_0_9999px_rgba(2,6,23,.2)]"/></div><p className="mt-5 text-center text-xs leading-5 text-slate-300">{message}</p><button onClick={onClose} className="mt-4 w-full rounded-xl border border-white/12 py-3 text-sm font-bold text-slate-200">手入力に戻る</button></section></div>;
}

function AdminBootstrap({ onClose }: { onClose: () => void }) {
  const auth=trpc.siteAdmin.me.useQuery(); const login=trpc.siteAdmin.login.useMutation(); const createRoom=trpc.classroom.rooms.create.useMutation(); const createOwner=trpc.classroom.members.createPinAccount.useMutation(); const utils=trpc.useUtils(); const [password,setPassword]=useState(""); const [name,setName]=useState(""); const [code,setCode]=useState(""); const [owner,setOwner]=useState(""); const [pin,setPin]=useState("");
  const signIn=async(event:React.FormEvent)=>{event.preventDefault();try{await login.mutateAsync({password});setPassword("");await utils.siteAdmin.me.invalidate();toast.success("全体管理者として認証しました。");}catch(error){toast.error(error instanceof Error?error.message:"認証できませんでした。");}};
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!/^[A-Z0-9-]{3,32}$/.test(code.trim().toUpperCase()))return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");if(!/^[0-9]{4}$/.test(pin))return toast.error("オーナーPINは4桁の数字で入力してください。");try{const room=await createRoom.mutateAsync({name:name.trim(),code:code.trim().toUpperCase()});if(!room.id)throw new Error("教室を作成できませんでした。");await createOwner.mutateAsync({classroomId:room.id,displayName:owner.trim(),pin,classroomRole:"owner"});toast.success("教室とオーナーPINを作成しました。PINは安全な場所で管理してください。");onClose();}catch(error){toast.error(error instanceof Error?error.message:"初期設定を保存できませんでした。");}};
  if(auth.isLoading)return <Modal title="管理者の初期設定" onClose={onClose}><p className="py-6 text-sm text-slate-300">管理者情報を確認しています…</p></Modal>;
  if(auth.data?.role!=="admin")return <Modal title="全体管理者ログイン" onClose={onClose}><p className="mt-4 text-sm leading-6 text-slate-300">このサイト固有の全体管理者パスワードを入力してください。外部アカウントとの連携は不要です。</p><form onSubmit={signIn}><label className="mt-5 block text-xs font-bold text-slate-200">全体管理者パスワード<input autoFocus required type="password" value={password} onChange={event=>setPassword(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="パスワードを入力"/></label><button disabled={login.isPending} className="mt-4 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{login.isPending?"認証しています…":"全体管理者として認証"}</button></form></Modal>;
  return <Modal title="教室とオーナーPINを作成" onClose={onClose}><form onSubmit={submit} className="mt-4 space-y-3"><label className="block text-xs font-bold text-slate-200">教室名<input required value={name} onChange={event=>setName(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：東南学習教室"/></label><label className="block text-xs font-bold text-slate-200">教室コード<input required value={code} onChange={event=>setCode(event.target.value.toUpperCase())} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：STAR-2026"/></label><label className="block text-xs font-bold text-slate-200">オーナー表示名<input required value={owner} onChange={event=>setOwner(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：教室管理者"/></label><label className="block text-xs font-bold text-slate-200">オーナーPIN<input required inputMode="numeric" maxLength={4} value={pin} onChange={event=>setPin(event.target.value.replace(/\D/g,""))} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-center font-mono text-lg tracking-[.4em]" placeholder="••••"/></label><p className="text-[10px] leading-4 text-slate-400">PINは保存後に表示できません。作成直後に安全な経路で管理者へ共有してください。</p><button disabled={createRoom.isPending||createOwner.isPending} className="w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{createRoom.isPending||createOwner.isPending?"作成しています…":"教室とPINを作成"}</button></form></Modal>;
}

function TeacherAdminLogin({ onClose, onAuthenticated }: { onClose: () => void; onAuthenticated: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void }) {
  const login = trpc.teacherAdmin.login.useMutation();
  const utils = trpc.useUtils();
  const [teacherId, setTeacherId] = useState("");
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    const id = Number(teacherId);
    if (!Number.isInteger(id) || id <= 0) return toast.error("先生IDは正の整数で入力してください。");
    try {
      const result = await login.mutateAsync({ teacherId: id });
      await utils.teacherAdmin.me.invalidate();
      onAuthenticated(result.teacher);
      toast.success(`${result.teacher.classroomName}の先生管理画面を開きました。`);
      onClose();
    } catch (error) { toast.error(error instanceof Error ? error.message : "先生IDを確認できませんでした。"); }
  };
  return <Modal title="先生IDで管理画面へ" onClose={onClose}><p className="mt-3 text-sm leading-6 text-slate-300">全体管理者とは別に、担当教室に設定された先生IDでログインします。表示・操作できる内容は担当教室だけに限定されます。</p><form onSubmit={submit}><label className="mt-5 block text-xs font-bold text-slate-200">先生ID<input autoFocus required inputMode="numeric" value={teacherId} onChange={event => setTeacherId(event.target.value.replace(/\D/g, ""))} placeholder="例：1111" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" /></label><button disabled={login.isPending} className="mt-4 w-full rounded-xl bg-violet-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{login.isPending ? "認証しています…" : "先生管理画面を開く"}</button></form></Modal>;
}

function ManagementAccess({ onClose, onAdminAuthenticated, onTeacherAuthenticated }: { onClose: () => void; onAdminAuthenticated: () => void; onTeacherAuthenticated: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void }) {
  const [method, setMethod] = useState<"site" | "teacher">("site"); const [credential, setCredential] = useState("");
  const siteLogin = trpc.siteAdmin.login.useMutation(); const teacherLogin = trpc.teacherAdmin.login.useMutation(); const pinLogout = trpc.auth.pinLogout.useMutation(); const utils = trpc.useUtils(); const pending = siteLogin.isPending || teacherLogin.isPending || pinLogout.isPending;
  const submit = async (event: React.FormEvent) => { event.preventDefault(); try { await pinLogout.mutateAsync(); if (method === "site") { if (!credential.trim()) return toast.error("全体管理者パスワードを入力してください。"); await siteLogin.mutateAsync({ password: credential }); await utils.siteAdmin.me.invalidate(); onAdminAuthenticated(); toast.success("全体管理画面を開きました。"); } else { const teacherId = Number(credential); if (!Number.isInteger(teacherId) || teacherId <= 0) return toast.error("先生IDは正の整数で入力してください。"); const result = await teacherLogin.mutateAsync({ teacherId }); await utils.teacherAdmin.me.invalidate(); onTeacherAuthenticated(result.teacher); toast.success(`${result.teacher.classroomName}の先生管理画面を開きました。`); } setCredential(""); onClose(); } catch (error) { toast.error(error instanceof Error ? error.message : "管理者認証に失敗しました。入力内容を確認してください。"); } };
  return <Modal title="管理画面を開く" onClose={onClose}><p className="mt-3 text-sm leading-6 text-slate-300">認証方法を選んで入力してください。全体管理者は全教室を、先生は担当教室だけを管理できます。</p><form onSubmit={submit} className="mt-5"><label className="block text-xs font-bold text-slate-200">認証方法<select value={method} onChange={event => { setMethod(event.target.value as "site" | "teacher"); setCredential(""); }} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"><option value="site">全体管理者パスワード</option><option value="teacher">先生ID</option></select></label><label className="mt-4 block text-xs font-bold text-slate-200">{method === "site" ? "全体管理者パスワード" : "先生ID"}<input autoFocus required type={method === "site" ? "password" : "text"} inputMode={method === "teacher" ? "numeric" : undefined} value={credential} onChange={event => setCredential(method === "teacher" ? event.target.value.replace(/\D/g, "") : event.target.value)} placeholder={method === "site" ? "パスワードを入力" : "例：1111"} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label><button disabled={pending} className="mt-5 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{pending ? "認証しています…" : method === "site" ? "全体管理画面を開く" : "先生管理画面を開く"}</button></form></Modal>;
}

function MemberDetailSheet({ profileId, onClose }: { profileId: number; onClose: () => void }) {
  const detail = trpc.classroom.members.detail.useQuery({ profileId }, { retry: false });
  const duration = (seconds: number) => `${Math.floor(seconds / 3600)}時間${Math.floor((seconds % 3600) / 60)}分`;
  return <div className="fixed inset-0 z-50 bg-slate-950/65 p-3 sm:p-6" onClick={onClose}><section onClick={event => event.stopPropagation()} className="glass-card mx-auto flex max-h-[calc(100vh-24px)] w-full max-w-2xl flex-col overflow-hidden rounded-[28px]"><div className="flex items-start justify-between border-b border-white/10 p-5"><div><p className="eyebrow">learner profile</p><h2 className="mt-1 text-xl font-bold">{detail.data?.profile.displayName ?? "利用者詳細"}</h2><p className="mt-1 text-xs text-slate-400">{detail.data?.profile.classroomName ?? "学習情報を確認しています"}</p></div><button onClick={onClose} aria-label="詳細を閉じる" className="grid h-9 w-9 place-items-center rounded-xl bg-white/8"><X className="h-4 w-4"/></button></div><div className="min-h-0 overflow-y-auto p-5">{detail.isLoading && <p className="rounded-2xl bg-slate-950/30 p-4 text-sm text-slate-400">学習情報を読み込んでいます…</p>}{detail.isError && <div className="rounded-2xl border border-red-200/30 bg-red-400/10 p-4"><p className="text-sm font-bold text-red-100">利用者詳細を取得できませんでした</p><button onClick={() => void detail.refetch()} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100">再試行</button></div>}{detail.data && <div className="space-y-5"><section><p className="text-sm font-bold">総合学習</p><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><div className="rounded-2xl bg-cyan-300/10 p-3"><p className="text-[10px] text-slate-400">総合勉強時間</p><p className="mt-1 text-sm font-bold text-cyan-100">{duration(detail.data.learning.totalFocusSeconds)}</p></div><div className="rounded-2xl bg-violet-300/10 p-3"><p className="text-[10px] text-slate-400">回答数</p><p className="mt-1 text-lg font-bold text-violet-100">{detail.data.learning.records}問</p></div><div className="rounded-2xl bg-amber-300/10 p-3"><p className="text-[10px] text-slate-400">正答率</p><p className="mt-1 text-lg font-bold text-amber-100">{detail.data.learning.retention}%</p></div><div className="rounded-2xl bg-emerald-300/10 p-3"><p className="text-[10px] text-slate-400">連続学習</p><p className="mt-1 text-lg font-bold text-emerald-100">{detail.data.learning.streak}日</p></div></div></section><section className="rounded-2xl bg-white/[.04] p-4"><div className="flex items-center justify-between"><p className="text-sm font-bold">単語帳ごとの達成率</p><span className="text-xs text-slate-400">復習対象 {detail.data.reviewWordCount}語</span></div><div className="mt-3 space-y-3">{detail.data.wordbooks.length ? detail.data.wordbooks.map(book => <div key={book.id}><div className="flex justify-between gap-2 text-xs"><span className="truncate font-semibold">{book.title}</span><span className="shrink-0 text-slate-400">{book.masteredWordCount}/{book.wordCount}語・正答 {book.accuracyPercent}%</span></div><div className="mt-1.5 h-2 overflow-hidden rounded-full bg-slate-950/30"><div className="h-full rounded-full bg-gradient-to-r from-cyan-300 to-violet-300" style={{ width: `${book.progressPercent}%` }}/></div></div>) : <p className="text-xs text-slate-400">学習可能な単語帳はまだありません。</p>}</div></section><div className="grid gap-4 sm:grid-cols-2"><section className="rounded-2xl bg-white/[.04] p-4"><p className="text-sm font-bold">保存済み学習セット</p><div className="mt-3 space-y-2">{detail.data.savedSets.length ? detail.data.savedSets.map(set => <div key={set.id} className="rounded-xl bg-slate-950/25 px-3 py-2"><p className="text-xs font-bold">{set.label}</p><p className="mt-1 text-[10px] text-slate-400">{set.wordbookTitle}・{set.wordCount}語</p></div>) : <p className="text-xs text-slate-400">保存済みの学習セットはありません。</p>}</div></section><section className="rounded-2xl bg-white/[.04] p-4"><p className="text-sm font-bold">持ち物・育成</p><div className="mt-3 space-y-2 text-xs"><p>復活チケット：<b className="text-amber-100">{detail.data.profile.revivalTickets}枚</b></p><p>モンスター：卵{detail.data.monster.eggNumber}・進化 {detail.data.monster.stage}/13</p><p>保有卵：{detail.data.monster.eggCount}個　育成履歴：{detail.data.monster.historyCount}体</p><p className="text-slate-400">復活日利用：{detail.data.revivalHistory.length}件</p></div></section></div><section className="rounded-2xl bg-white/[.04] p-4"><p className="text-sm font-bold">最近の学習</p><div className="mt-3 space-y-2">{detail.data.recentAnswers.length ? detail.data.recentAnswers.map(answer => <div key={answer.id} className="flex items-center justify-between rounded-xl bg-slate-950/25 px-3 py-2 text-xs"><span>{answer.mode === "test" ? "テスト" : answer.mode === "practice" ? "練習" : answer.mode === "ai_select" ? "AIセレクト" : "学習"}・{answer.isCorrect ? "正解" : "復習"}</span><time className="text-slate-400">{new Date(answer.answeredAt).toLocaleString("ja-JP")}</time></div>) : <p className="text-xs text-slate-400">まだ回答の記録はありません。</p>}</div></section></div>}</div></section></div>;
}

function ClassroomMembersPanel() {
  const utils = trpc.useUtils();
  const members = trpc.classroom.members.list.useQuery(undefined, { retry: false, staleTime: 20_000 });
  const resetTickets = trpc.classroom.members.resetRevivalTickets.useMutation({ onSuccess: () => void utils.classroom.members.list.invalidate() });
  const [selectedProfileId, setSelectedProfileId] = useState<number | null>(null);
  const refillTickets = async (profileId: number) => {
    try { await resetTickets.mutateAsync({ profileId }); toast.success("復活チケットを2枚に補充しました。"); }
    catch (error) { toast.error(error instanceof Error ? error.message : "復活チケットを補充できませんでした。"); }
  };
  if (members.isLoading) return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">利用者を読み込んでいます…</p></section>;
  if (members.isError) return <section className="rounded-[24px] border border-red-200/20 bg-red-400/5 p-4" role="alert"><p className="text-sm font-bold text-red-100">利用者を取得できませんでした</p><button onClick={() => void members.refetch()} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100">再試行</button></section>;
  const rows = members.data ?? [];
  return <><section className="glass-card rounded-[24px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-300/12 text-cyan-100"><UserRound className="h-5 w-5" /></div><div><p className="text-sm font-bold">利用者</p><p className="mt-1 text-xs leading-5 text-slate-400">利用者をタップすると、総合勉強時間・正答率・単語帳の達成率などを確認できます。</p></div></div><div className="mt-4 space-y-2">{rows.length ? rows.map(member => <div key={member.id} className="flex flex-wrap items-center gap-3 rounded-xl bg-slate-950/30 p-3"><button type="button" onClick={() => setSelectedProfileId(member.id)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-cyan-300/12 text-xs font-bold text-cyan-100">{(member.displayName ?? "学").slice(0, 1)}</div><div className="min-w-0"><p className="truncate text-sm font-semibold">{member.displayName ?? `学習者 #${member.id}`}</p><p className="mt-1 text-[10px] text-slate-400">参加：{new Date(member.createdAt).toLocaleString("ja-JP")}</p></div></button><span className="rounded-full bg-white/8 px-2 py-1 text-[10px] text-slate-300">学習者</span><button type="button" onClick={() => void refillTickets(member.id)} disabled={resetTickets.isPending} className="w-full rounded-lg border border-amber-200/30 bg-amber-300/10 px-2 py-2 text-[10px] font-bold text-amber-100 disabled:opacity-60 sm:w-auto">{resetTickets.isPending ? "補充しています…" : "チケットを2枚へ戻す"}</button></div>) : <p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">まだ利用者はいません。最初のPINログイン後に自動で表示されます。</p>}</div></section>{selectedProfileId !== null && <MemberDetailSheet profileId={selectedProfileId} onClose={() => setSelectedProfileId(null)}/>}</>;
}

function LoginGate({ onEnter, onAdminEnter, onTeacherEnter }: { onEnter: (pin: string, classroom: string) => Promise<void>; onAdminEnter: () => void; onTeacherEnter: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void }) {
  const [pin, setPin] = useState("");
  const [classroom, setClassroom] = useState("");
  const [showHelp, setShowHelp] = useState(false);
  const [scanning,setScanning]=useState(() => new URLSearchParams(window.location.search).get("preview") === "qr"); const [submitting,setSubmitting]=useState(false); const [managementAccess,setManagementAccess]=useState(() => new URLSearchParams(window.location.search).get("preview") === "admin-setup");
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!isValidPin(pin)) return toast.error("PINは4桁の数字で入力してください。"); if (!isValidClassroomCode(classroom)) return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");setSubmitting(true);try{await onEnter(pin, normalizeClassroomCode(classroom));}finally{setSubmitting(false);} };
  return <main className="sky-shell relative grid min-h-screen place-items-center overflow-hidden px-5 py-10"><div className="star-field" /><div className="absolute -left-24 top-8 h-64 w-64 rounded-full bg-cyan-300/10 blur-3xl" /><motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .45 }} className="glass-card relative w-full max-w-[430px] rounded-[32px] p-6 sm:p-8">
    <div className="mb-8 flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-gradient-to-br from-cyan-200 to-violet-400 text-slate-950 shadow-[0_0_25px_rgba(122,232,226,.35)]"><Sparkles className="h-5 w-5" /></div><div><p className="text-xl font-extrabold tracking-[-.04em]">StudyVerse</p><p className="font-mono text-[10px] uppercase tracking-[.18em] text-cyan-200">learning orbit</p></div></div><MoonStar className="h-5 w-5 text-slate-400" /></div>
    <div><p className="eyebrow">entry portal</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.05em]">学びを、続ける軌道へ。</h1><p className="mt-3 text-sm leading-6 text-slate-300">4桁PINと教室コードで、あなたの学習空間を開きます。</p></div>
    <form onSubmit={submit} className="mt-7 space-y-5"><label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">4桁 PIN</span><div className="relative"><KeyRound className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-cyan-200" /><input autoFocus inputMode="numeric" maxLength={4} value={pin} onChange={e => setPin(e.target.value.replace(/\D/g, ""))} placeholder="• • • •" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-4 text-center font-mono text-xl tracking-[.45em] text-white placeholder:tracking-[.3em] placeholder:text-slate-600" /></div></label>
      <label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">教室コード</span><div className="relative"><GraduationCap className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-violet-200" /><input value={classroom} onChange={e => setClassroom(e.target.value.toUpperCase())} placeholder="例：STAR-2026" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-12 text-sm text-white placeholder:text-slate-500" /><button type="button" aria-label="教室コードを読み取る" onClick={() => setScanning(true)} className="absolute right-2 top-1/2 grid h-9 w-9 -translate-y-1/2 place-items-center rounded-xl text-cyan-200 transition hover:bg-white/10"><ScanLine className="h-5 w-5" /></button></div></label>
      <button disabled={submitting} type="submit" className="glow-pulse w-full rounded-2xl bg-gradient-to-r from-cyan-300 via-teal-200 to-cyan-300 py-4 text-sm font-extrabold text-slate-950 transition hover:brightness-110 active:scale-[.98] disabled:opacity-60">{submitting?"認証しています…":"学習空間をひらく"} <ArrowRight className="ml-1 inline h-4 w-4" /></button></form>
    <button onClick={() => setShowHelp(!showHelp)} className="mt-5 w-full text-center text-xs text-slate-400 underline-offset-4 hover:text-cyan-200 hover:underline">教室コードが分からない場合</button>{showHelp && <p className="mt-3 rounded-xl bg-white/6 p-3 text-xs leading-5 text-slate-300">先生から共有された教室コードを確認してください。コードがない場合は、先生または管理者に発行を依頼してください。</p>}<button onClick={()=>setManagementAccess(true)} className="mt-3 w-full text-center text-xs font-bold text-violet-200 hover:underline">管理画面を開く</button>
    <p className="mt-8 text-center font-mono text-[9px] leading-4 tracking-wide text-slate-500">PINは4桁の数字のみを受け付けます。<br />同じPINでも教室が異なれば別の学習空間として扱います。</p>{scanning&&<QrScannerModal onClose={()=>setScanning(false)} onDetected={value=>{if(!/^[A-Za-z0-9-]{3,32}$/.test(value)){toast.error("QRコード内の教室コード形式が正しくありません。");return;}setClassroom(value.toUpperCase());setScanning(false);toast.success("教室コードを読み取りました。");}}/>}{managementAccess&&<ManagementAccess onClose={()=>setManagementAccess(false)} onAdminAuthenticated={onAdminEnter} onTeacherAuthenticated={onTeacherEnter}/>} 
  </motion.section></main>;
}

export function Header({ page, onBack, onProfile, onNavigate, timerStripVisible = false }: { page: string; onBack: () => void; onProfile: () => void; onNavigate?: (page: "books" | "cards") => void; timerStripVisible?: boolean }) {
  const { theme, toggleTheme } = useTheme();
  const announcements = trpc.classroom.announcements.list.useQuery(undefined, { retry: false, staleTime: 30_000 });
  const announcementTests = trpc.classroom.recommendedTests.announcements.useQuery(undefined, { retry: false, staleTime: 30_000 });
  const claimTest = trpc.classroom.recommendedTests.claim.useMutation(); const claimWordbook = trpc.classroom.recommendedTests.claimWordbook.useMutation();
  const utils = trpc.useUtils();
  const [noticeOpen, setNoticeOpen] = useState(false);
  const [seenUntil, setSeenUntil] = useState(() => {
    try { return Number(window.localStorage.getItem("studyverse-announcements-seen-at")) || 0; } catch { return 0; }
  });
  const newestAnnouncementAt = Math.max(0, ...(announcements.data ?? []).map(item => new Date(item.publishedAt).getTime()));
  const newestTestAt = Math.max(0, ...(announcementTests.data ?? []).map(item => new Date(item.createdAt).getTime()));
  const newestAt = Math.max(newestAnnouncementAt, newestTestAt);
  const hasUnread = newestAt > seenUntil;
  const openNotices = () => {
    setNoticeOpen(true);
    if (newestAt) {
      setSeenUntil(newestAt);
      try { window.localStorage.setItem("studyverse-announcements-seen-at", String(newestAt)); } catch { /* 保存不可の環境ではこの画面表示中のみ既読にする */ }
    }
  };
  const receiveTest = async (item: { id: number; deliveryType?: "test" | "wordbook" }) => {
    try {
      const result = item.deliveryType === "wordbook" ? await claimWordbook.mutateAsync({ recommendedTestId: item.id }) : await claimTest.mutateAsync({ recommendedTestId: item.id });
      await Promise.all([utils.classroom.recommendedTests.announcements.invalidate(), utils.classroom.recommendedTests.list.invalidate(), utils.wordbooks.list.invalidate(), utils.learning.dashboard.invalidate()]);
      toast.success(result.alreadyClaimed ? "この教材はすでに追加されています。" : "教材を自分の学習場所へ追加しました。"); onNavigate?.(item.deliveryType === "wordbook" ? "books" : "cards");
    } catch (error) { toast.error(error instanceof Error ? error.message : "教材を受け取れませんでした。"); }
  };
  return <><header className={`theme-header sticky ${timerStripVisible ? "top-8" : "top-0"} z-30 border-b border-white/[.06] px-4 py-3 backdrop-blur-xl`}><div className="mx-auto flex max-w-5xl items-center justify-between"><div className="flex items-center gap-2"><button onClick={onBack} className="grid h-9 w-9 place-items-center rounded-xl border border-white/10 bg-white/5 text-slate-300 transition hover:bg-white/10" aria-label="前の画面に戻る"><ArrowLeft className="h-4 w-4" /></button><div><p className="text-sm font-extrabold tracking-[-.04em]">{page}</p><p className="font-mono text-[9px] tracking-[.16em] text-cyan-200">STUDYVERSE</p></div></div><div className="flex items-center gap-2"><button onClick={toggleTheme} className="grid h-9 w-9 place-items-center rounded-xl border border-white/10 bg-white/5 text-slate-300 transition hover:bg-white/10" aria-label={theme === "dark" ? "明るい表示へ切り替える" : "ダーク表示へ切り替える"}>{theme === "dark" ? <MoonStar className="h-4 w-4" /> : <Sparkles className="h-4 w-4" />}</button><button onClick={openNotices} className={`relative grid h-9 w-9 place-items-center rounded-xl border border-white/10 bg-white/5 text-slate-300 transition hover:bg-white/10 ${hasUnread ? "shadow-[0_0_18px_rgba(103,232,249,.72)]" : ""}`} aria-label="お知らせを開く"><Bell className="h-4 w-4" />{hasUnread && <i className="absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-cyan-300 shadow-[0_0_10px_rgba(103,232,249,1)] animate-pulse" />}</button><button onClick={onProfile} className="grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-violet-300 to-cyan-200 text-slate-950" aria-label="プロフィールを開く"><UserRound className="h-4 w-4" /></button></div></div></header>{noticeOpen && <div className="fixed inset-0 z-50 bg-slate-950/65 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="お知らせ一覧"><section className="glass-card mx-auto mt-14 max-h-[calc(100vh-7rem)] w-full max-w-lg overflow-y-auto rounded-[28px] p-5"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow">announcements</p><h2 className="mt-1 text-xl font-bold">お知らせ</h2><p className="mt-1 text-xs text-slate-400">新着のお知らせと、受け取れる教室教材を表示します。</p></div><button onClick={() => setNoticeOpen(false)} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8 text-slate-200" aria-label="お知らせを閉じる"><X className="h-4 w-4" /></button></div><div className="mt-5 space-y-3">{announcements.isLoading || announcementTests.isLoading ? <p className="rounded-2xl bg-slate-950/30 p-4 text-sm text-slate-400">お知らせを読み込んでいます…</p> : announcements.isError || announcementTests.isError ? <div className="rounded-2xl bg-red-400/10 p-4 text-sm text-red-100">お知らせを取得できませんでした。<button onClick={() => { void announcements.refetch(); void announcementTests.refetch(); }} className="mt-2 block text-xs font-bold underline">再試行</button></div> : <>{(announcements.data ?? []).map(item => <article key={`notice-${item.id}`} className="rounded-2xl border border-cyan-200/10 bg-slate-950/30 p-4"><div className="flex items-start justify-between gap-3"><h3 className="text-sm font-bold">{item.title}</h3>{new Date(item.publishedAt).getTime() > seenUntil && <span className="rounded-full bg-cyan-300/15 px-2 py-1 text-[10px] font-bold text-cyan-100">新着</span>}</div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-300">{item.body}</p><time className="mt-3 block text-[10px] text-slate-500">{new Date(item.publishedAt).toLocaleString("ja-JP")}</time></article>)}{(announcementTests.data ?? []).map(item => <article key={`test-${item.id}`} className="rounded-2xl border border-violet-200/15 bg-violet-300/[.06] p-4"><div className="flex items-start justify-between gap-3"><div><span className="rounded-full bg-violet-300/15 px-2 py-1 text-[10px] font-bold text-violet-100">教材配布</span><h3 className="mt-3 text-sm font-bold">{item.wordbookTitle}</h3></div>{!item.claimed && <span className="rounded-full bg-cyan-300/15 px-2 py-1 text-[10px] font-bold text-cyan-100">未受取</span>}</div><p className="mt-2 text-xs leading-5 text-slate-300">{item.deliveryType === "wordbook" ? "単語帳全体を配布しています。" : `第${item.rangeStart}〜${item.rangeEnd}語をおすすめテストとして配布しています。`}受け取ると、{item.deliveryType === "wordbook" ? "単語帳ページ" : "単語カード画面"}へ移動します。</p><p className="mt-2 text-[10px] text-slate-500">表示終了：{item.availableUntil ? new Date(item.availableUntil).toLocaleString("ja-JP") : "設定なし"}</p><button disabled={item.claimed || claimTest.isPending || claimWordbook.isPending} onClick={() => void receiveTest(item)} className="mt-3 w-full rounded-xl bg-cyan-300 py-2.5 text-xs font-bold text-slate-950 disabled:cursor-not-allowed disabled:opacity-50">{item.claimed ? "受取済み" : claimTest.isPending ? "受け取っています…" : "受け取る"}</button></article>)}{!(announcements.data ?? []).length && !(announcementTests.data ?? []).length && <p className="rounded-2xl bg-slate-950/30 p-4 text-sm text-slate-400">現在のお知らせはありません。</p>}</>}</div></section></div>}</>;
}

export function TimerStrip({ running, elapsed, durationMinutes, onToggle }: { running: boolean; elapsed: number; durationMinutes: number; onToggle: () => void }) {
  const duration = durationMinutes * 60;
  const remaining = Math.max(duration - elapsed, 0);
  const remainingPercent = running ? Math.max(0, Math.min(remaining / duration, 1) * 100) : 0;
  return <div className="fixed inset-x-0 top-0 z-50 border-b border-border/70 bg-background/90 px-3 py-1.5 shadow-sm backdrop-blur-xl"><div className="mx-auto flex max-w-5xl items-center gap-2"><span className="shrink-0 text-[10px] font-bold text-foreground">タイマー</span><div className="relative h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-muted" aria-label="タイマー残り時間"><div className="absolute inset-y-0 left-0 rounded-full bg-cyan-400 transition-[width] duration-500" style={{ width: `${remainingPercent}%` }} /></div><span className="shrink-0 font-mono text-[11px] font-bold text-foreground" aria-label="残り時間">{formatSeconds(remaining)}</span><button onClick={onToggle} className={`shrink-0 rounded-full px-2.5 py-1 text-[10px] font-bold transition active:scale-[.97] ${running ? "bg-cyan-300 text-slate-950" : "bg-muted text-foreground"}`} aria-label={running ? "タイマーをオフにする" : "タイマーをオンにする"}>{running ? "ON" : "OFF"}</button></div></div>;
}

export function TimerCard({ running, elapsed, durationMinutes, showTopTimer, onToggle, onReset, onDurationChange, onShowTopTimerChange }: { running: boolean; elapsed: number; durationMinutes: number; showTopTimer: boolean; onToggle: () => void; onReset: () => void; onDurationChange: (minutes: number) => void; onShowTopTimerChange: (show: boolean) => void }) {
  const [durationOpen, setDurationOpen] = useState(false);
  const duration = durationMinutes * 60; const percentage = Math.min(elapsed / duration, 1) * 100;
  const durationOptions = [5, 10, 15, 20, 25, 30, 40, 50, 60, 90, 120, 180];
  const selectableDurations = durationOptions.includes(durationMinutes) ? durationOptions : [durationMinutes, ...durationOptions].sort((a, b) => a - b);
  return <section className="glass-card rounded-[26px] p-4"><div className="flex items-start justify-between"><div><p className="eyebrow">focus timer</p><h2 className="mt-1 text-lg font-bold">集中モード</h2></div><span className="rounded-full bg-violet-300/13 px-2.5 py-1 font-mono text-[10px] text-violet-100">{durationMinutes}分</span></div><div className="mt-4 flex items-center gap-4"><div className="relative grid h-20 w-20 place-items-center rounded-full" style={{ background: `conic-gradient(#78ebe1 ${percentage}%, rgba(255,255,255,.09) 0)` }}><div className="theme-timer-core grid h-[66px] w-[66px] place-items-center rounded-full"><span className="font-mono text-sm font-bold">{formatSeconds(Math.max(duration - elapsed, 0))}</span></div></div><div className="flex-1"><p className="text-sm font-semibold">{durationMinutes}分、ひとつだけに集中。</p><p className="mt-1 text-xs leading-5 text-slate-400">タイマーは画面を移動しても時刻基準で続きます。</p><div className="mt-3 flex gap-2"><button onClick={onToggle} className="rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950 active:scale-[.97]">{running ? <><Pause className="mr-1 inline h-3.5 w-3.5" />一時停止</> : <><Play className="mr-1 inline h-3.5 w-3.5" />開始</>}</button><button onClick={onReset} className="rounded-xl border border-white/12 px-3 py-2 text-xs text-slate-200 transition hover:bg-white/8"><TimerReset className="mr-1 inline h-3.5 w-3.5" />リセット</button></div></div></div><div className="mt-4 border-t border-white/10 pt-4"><button type="button" aria-expanded={durationOpen} onClick={() => setDurationOpen(open => !open)} className="flex w-full items-center justify-between rounded-xl bg-white/[.055] px-3 py-2.5 text-left text-xs font-bold text-slate-200"><span>タイマー時間：{durationMinutes}分</span><ChevronDown className={`h-4 w-4 transition-transform ${durationOpen ? "rotate-180" : ""}`}/></button>{durationOpen && <label className="mt-3 block text-xs font-bold text-slate-300">時間を選択<select aria-label="集中時間（分）" value={durationMinutes} disabled={running} onChange={event => { onDurationChange(Number(event.target.value)); setDurationOpen(false); }} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2 text-sm disabled:opacity-50">{selectableDurations.map(minutes => <option key={minutes} value={minutes}>{minutes}分</option>)}</select></label>}<label className="mt-3 flex cursor-pointer items-center gap-2 text-xs font-bold text-slate-300"><input type="checkbox" checked={showTopTimer} onChange={event => onShowTopTimerChange(event.target.checked)} className="h-4 w-4 accent-cyan-300"/>作動中に上部タイマーを表示</label></div></section>;
}

export function HomeView({ setPage, onOpenReview, onPreloadAiSelect, running, elapsed, timerDurationMinutes, showTopTimer, onToggleTimer, onResetTimer, onDurationChange, onShowTopTimerChange, summary, displayName, isPersonalUse = false }: { setPage: (page: NavKey) => void; onOpenReview: () => void; onPreloadAiSelect: () => void; running: boolean; elapsed: number; timerDurationMinutes: number; showTopTimer: boolean; onToggleTimer: () => void; onResetTimer: () => void; onDurationChange: (minutes: number) => void; onShowTopTimerChange: (show: boolean) => void; summary?: { totalFocusSeconds: number; retention: number; streak: number; records: number }; displayName?: string | null; isPersonalUse?: boolean }) {
  const [panel, setPanel] = useState(0); const totalSeconds=Math.max(0, (summary?.totalFocusSeconds??0) + (running ? elapsed : 0)); const totalHours=Math.floor(totalSeconds/3600); const remainingMinutes=Math.floor((totalSeconds%3600)/60); const remainingSeconds=totalSeconds%60; const totalFocusLabel=totalHours>0?`${totalHours}h ${remainingMinutes}m ${remainingSeconds}s`:`${remainingMinutes}m ${remainingSeconds}s`; const calendar = trpc.classroom.calendar.list.useQuery(undefined, { retry: false, staleTime: 30_000 }); const dashboard = trpc.learning.dashboard.useQuery(undefined, { retry: false, staleTime: 30_000 }); const reviewWords = dashboard.data?.reviewWords ?? []; const unstartedSets = dashboard.data?.unstartedSets ?? [];
  const panels = [<LearningCalendar key="calendar" />, <MonsterGrowthPanel key="monster" liveFocusSeconds={running ? elapsed : 0} />, <MonsterMissionPanel key="mission" />];
  return <div className="space-y-4 px-4 pb-28 pt-5"><section className="theme-home-hero relative overflow-hidden rounded-[28px] border border-cyan-100/10 p-5 shadow-[0_20px_55px_rgba(4,10,28,.35)]"><div className="soft-grid absolute inset-0 opacity-40" /><div className="relative"><div className="flex items-start justify-between"><div><p className="eyebrow text-cyan-100">your learning orbit</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.06em]">StudyVerse</h1><p className="mt-1 text-xs text-slate-200">今日の小さな前進を、未来の力に。</p>{displayName && <p className="mt-3 inline-flex rounded-full bg-white/15 px-3 py-1.5 text-xs font-bold text-white">ようこそ、{displayName}さん</p>}</div><div className="orb-float grid h-11 w-11 place-items-center rounded-2xl bg-cyan-200/16 text-cyan-100"><Sparkles className="h-5 w-5" /></div></div><div className="mt-6 grid grid-cols-3 divide-x divide-white/10"><div><p className="font-mono text-[10px] text-slate-300">TOTAL</p><p className="mt-1 text-lg font-bold">{totalFocusLabel}</p></div><div className="pl-3"><p className="font-mono text-[10px] text-slate-300">RETAIN</p><p className="mt-1 text-lg font-bold">{summary?.retention??0}<span className="ml-1 text-xs font-medium text-slate-300">%</span></p></div><div className="pl-3"><p className="font-mono text-[10px] text-slate-300">STREAK</p><p className="mt-1 text-lg font-bold">{summary?.streak??0}<span className="ml-1 text-xs font-medium text-slate-300">days</span></p></div></div></div></section>
    <LearningTrendChart liveFocusSeconds={running ? elapsed : 0} />
    <section><div className="mb-2 flex items-center justify-between"><div><p className="eyebrow">orbit panels</p><h2 className="mt-1 text-lg font-bold">学習の現在地</h2></div><div className="flex gap-1.5">{[0,1,2].map(i => <button key={i} aria-label={`パネル${i+1}`} onClick={() => setPanel(i)} className={`h-1.5 rounded-full transition-all ${i===panel ? "w-6 bg-cyan-200" : "w-1.5 bg-white/20"}`} />)}</div></div><AnimatePresence mode="wait"><motion.div key={panel} drag="x" dragConstraints={{ left: 0, right: 0 }} dragElastic={.12} onDragEnd={(_, info) => { if (info.offset.x > 45) setPanel(Math.max(0, panel - 1)); if (info.offset.x < -45) setPanel(Math.min(2, panel + 1)); }} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -16 }} transition={{ duration: .18 }}>{panels[panel]}</motion.div></AnimatePresence><div className="mt-2 flex justify-between px-2"><button onClick={() => setPanel(Math.max(0,panel-1))} disabled={panel===0} className="text-xs text-slate-400 disabled:opacity-30"><ChevronLeft className="mr-1 inline h-4 w-4" />前へ</button><button onClick={() => setPanel(Math.min(2,panel+1))} disabled={panel===2} className="text-xs text-slate-400 disabled:opacity-30">次へ<ArrowRight className="ml-1 inline h-4 w-4" /></button></div></section>
    <TimerCard running={running} elapsed={elapsed} durationMinutes={timerDurationMinutes} showTopTimer={showTopTimer} onToggle={onToggleTimer} onReset={onResetTimer} onDurationChange={onDurationChange} onShowTopTimerChange={onShowTopTimerChange}/>
    <section><button onPointerEnter={onPreloadAiSelect} onFocus={onPreloadAiSelect} onClick={() => { onPreloadAiSelect(); setPage("aiSelect"); }} className="glass-card group w-full rounded-[25px] p-4 text-left transition hover:-translate-y-0.5 hover:border-violet-200/30"><BrainCircuit className="h-5 w-5 text-violet-200" /><p className="mt-4 text-base font-bold">AI セレクト 10</p><p className="mt-1 text-xs leading-5 text-slate-400">教室の教材から、今日の最大10語。</p><span className="mt-3 inline-block text-xs font-bold text-violet-200 group-hover:translate-x-1 transition-transform">専用ページを開く <ArrowRight className="inline h-3.5 w-3.5" /></span></button></section>
    {(reviewWords.length > 0 || unstartedSets.length > 0) && <section className="glass-card rounded-[25px] p-4"><div className="flex gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-amber-300/12 text-amber-200"><Bell className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-bold">復習リマインド</p>{reviewWords.length > 0 && <p className="mt-1 text-xs leading-5 text-slate-400">間違えた単語：{reviewWords.slice(0, 3).map(word => word.front).join("・")}{reviewWords.length > 3 ? ` ほか${reviewWords.length - 3}語` : ""}</p>}{unstartedSets.length > 0 && <p className="mt-1 text-xs leading-5 text-slate-400">まだ始めていないセット：{unstartedSets.slice(0, 2).map(set => set.label).join("・")}{unstartedSets.length > 2 ? " ほか" : ""}</p>}<button onClick={onOpenReview} className="mt-2 text-xs font-bold text-cyan-200">復習をひらく <ArrowRight className="inline h-3.5 w-3.5" /></button></div></div></section>}
    {!isPersonalUse && (<section><button onClick={() => setPage("online")} className="glass-card group flex w-full items-center gap-3 rounded-[25px] p-4 text-left transition hover:-translate-y-0.5 hover:border-cyan-200/30"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-cyan-300/12 text-cyan-200"><UsersRound className="h-5 w-5" /></div><div className="min-w-0 flex-1"><p className="text-sm font-bold">オンライン状況</p><p className="mt-1 text-xs leading-5 text-slate-400">同じ教室で学習中の仲間と、今日の進み具合を確認します。</p></div><ArrowRight className="h-4 w-4 text-cyan-200 transition-transform group-hover:translate-x-1" /></button></section>)}
  </div>;
}

function OnlineStatusPage() {
  const status = trpc.classroom.online.list.useQuery(undefined, { retry: false, refetchInterval: 30_000 });
  const [selectedProfileId, setSelectedProfileId] = useState<number | null>(null);
  const selected = status.data?.members.find(member => member.profileId === selectedProfileId);
  const duration = (seconds: number) => `${Math.floor(seconds / 3600)}時間${Math.floor((seconds % 3600) / 60)}分`;
  return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[28px] p-5"><div className="flex items-start gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-cyan-300/12 text-cyan-200"><Wifi className="h-5 w-5" /></div><div><p className="eyebrow">classroom presence</p><h1 className="mt-1 text-2xl font-extrabold">オンライン状況</h1><p className="mt-2 text-xs leading-5 text-slate-400">{status.data?.classroom.name ?? "同じ教室"}の利用者を表示します。緑色に光っている人が現在オンラインです。</p></div></div></section>{status.isLoading && <section className="glass-card rounded-[24px] p-4 text-sm text-slate-400">オンライン状況を確認しています…</section>}{status.isError && <section className="rounded-[24px] border border-red-200/25 bg-red-400/10 p-4"><p className="text-sm font-bold text-red-100">オンライン状況を取得できませんでした</p><button onClick={() => void status.refetch()} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100">再試行</button></section>}<section className="glass-card rounded-[26px] p-4"><div className="flex items-center justify-between"><p className="text-sm font-bold">教室メンバー</p><span className="text-xs text-slate-400">オンライン {(status.data?.members ?? []).filter(member => member.online).length}人</span></div><div className="mt-4 grid grid-cols-3 gap-4 sm:grid-cols-5">{(status.data?.members ?? []).map(member => <button key={member.profileId} onClick={() => setSelectedProfileId(member.profileId)} className="group flex flex-col items-center text-center"><span className={`relative grid h-16 w-16 place-items-center overflow-hidden rounded-full border-2 text-lg font-extrabold transition ${member.online ? "border-emerald-300 shadow-[0_0_24px_rgba(110,231,183,.65)]" : "border-white/15 bg-white/5 text-slate-400"}`}>{member.avatarUrl ? <img src={member.avatarUrl} alt="" className="h-full w-full object-cover" /> : (member.displayName ?? "学").slice(0, 1)}{member.online && <i className="absolute bottom-0.5 right-0.5 h-3.5 w-3.5 rounded-full border-2 border-[#0b1730] bg-emerald-300" />}</span><span className="mt-2 max-w-full truncate text-xs font-bold">{member.displayName ?? `学習者 #${member.profileId}`}{member.isSelf ? "（自分）" : ""}</span></button>)}</div>{!status.isLoading && !(status.data?.members.length) && <p className="rounded-xl bg-white/5 p-4 text-xs text-slate-400">同じ教室の利用者はまだいません。</p>}</section>{selected && <section className="glass-card rounded-[26px] p-5"><div className="flex items-center gap-3"><span className={`grid h-14 w-14 shrink-0 place-items-center overflow-hidden rounded-full border-2 ${selected.online ? "border-emerald-300 shadow-[0_0_18px_rgba(110,231,183,.55)]" : "border-white/15"}`}>{selected.avatarUrl ? <img src={selected.avatarUrl} alt="" className="h-full w-full object-cover" /> : (selected.displayName ?? "学").slice(0, 1)}</span><div><p className="text-lg font-bold">{selected.displayName ?? `学習者 #${selected.profileId}`}</p><p className={`mt-1 text-xs font-bold ${selected.online ? "text-emerald-300" : "text-slate-400"}`}>{selected.online ? "オンライン" : selected.lastSeenAt ? `最終接続 ${new Date(selected.lastSeenAt).toLocaleString("ja-JP")}` : "オフライン"}</p></div></div><div className="mt-5 grid grid-cols-3 gap-2"><div className="rounded-2xl bg-cyan-300/10 p-3"><p className="text-[10px] text-slate-400">今日の学習時間</p><p className="mt-1 text-sm font-bold text-cyan-100">{duration(selected.todayFocusSeconds)}</p></div><div className="rounded-2xl bg-violet-300/10 p-3"><p className="text-[10px] text-slate-400">今日覚えた単語</p><p className="mt-1 text-sm font-bold text-violet-100">{selected.todayMasteredWords}語</p></div><div className="rounded-2xl bg-amber-300/10 p-3"><p className="text-[10px] text-slate-400">モンスター</p><p className="mt-1 text-sm font-bold text-amber-100">卵{selected.monster.eggNumber}・{selected.monster.stage}/13</p></div></div></section>}</div>;
}

function BooksView({ books, setBooks, setPage }: { books: Record<Subject, Book[]>; setBooks: React.Dispatch<React.SetStateAction<Record<Subject, Book[]>>>; setPage: (page: NavKey) => void }) {
  const [subject, setSubject] = useState<Subject>("英単語"); const [selected, setSelected] = useState<Book | null>(null); const [creating, setCreating] = useState(false); const [title, setTitle] = useState("");
  const utils=trpc.useUtils(); const savedBooks=trpc.wordbooks.list.useQuery({subject:subject==="英単語"?"english":"kanji"},{retry:false}); const learningDashboard=trpc.learning.dashboard.useQuery(undefined,{retry:false,staleTime:30_000}); const createRemote=trpc.wordbooks.create.useMutation(); const creationPolicy=trpc.siteAdmin.wordbookCreationPolicy.useQuery(undefined,{retry:false,staleTime:30_000}); const creationDisabled=creationPolicy.data?.disabled === true;
  const library:Book[] = savedBooks.data ? savedBooks.data.map((book,index)=>({id:String(book.id),remoteId:book.id,name:book.title,count:book.wordCount,scope:book.visibility==="classroom"?"教室公開":book.visibility==="global"?"全体公開":"自分の教材",tone:index%2?"from-violet-400 to-indigo-500":"from-cyan-400 to-blue-500",canEdit:book.canEdit,words:book.words.map(word=>({id:word.id,front:word.front,back:word.back,reading:word.reading??undefined}))})) : books[subject];
  const createBook = async () => { if (!title.trim()) return toast.error("単語帳名を入力してください。"); try { await createRemote.mutateAsync({title:title.trim(),subject:subject==="英単語"?"english":"kanji",visibility:"private"}); await utils.wordbooks.list.invalidate(); setTitle("");setCreating(false);toast.success("単語帳を保存しました。"); } catch(error) { toast.error(error instanceof Error?error.message:"単語帳を保存できませんでした。"); } };
  return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-4"><p className="eyebrow">wordbook library</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">単語帳</h1><p className="mt-2 text-xs leading-5 text-slate-400">自分の教材と、教室で公開された教材を整理します。</p><div className="mt-5 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語","漢字"] as Subject[]).map(item => <button key={item} onClick={() => setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold transition ${item===subject ? "bg-white text-slate-950 shadow" : "text-slate-400"}`}>{item === "漢字" ? "その他" : item}</button>)}</div></section>
    <div className="flex items-center justify-between"><h2 className="text-sm font-bold">{subject === "漢字" ? "その他" : subject}の単語帳 <span className="ml-1 font-mono text-xs font-normal text-slate-500">{library.length}冊</span></h2><button disabled={creationDisabled} onClick={() => setCreating(true)} className={`rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950 transition ${creationDisabled ? "cursor-not-allowed opacity-35 grayscale" : ""}`}><Plus className="mr-1 inline h-3.5 w-3.5" />{creationDisabled ? "新規作成停止中" : "新規作成"}</button></div>
    {creationDisabled && <div className="rounded-xl border border-slate-300/30 bg-slate-400/20 px-3 py-2 text-xs text-slate-500">管理者により、新しい単語帳の作成が停止されています。既存の単語帳は閲覧・学習できます。</div>}<div className="space-y-2.5">{savedBooks.isLoading?<p className="text-xs text-slate-400">単語帳を読み込んでいます…</p>:library.length?library.map((book,index) => { const progress=learningDashboard.data?.wordbooks.find(item => item.id === book.remoteId); return <button onClick={() => setSelected(book)} key={book.id} className="glass-card flex w-full items-center gap-3 rounded-[22px] p-3 text-left transition hover:border-cyan-100/30"><div className={`grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-gradient-to-br ${book.tone} text-slate-950`}><BookOpen className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-bold">{book.name}</p>{isLearnerOnlyBook(book) && <span className="rounded-full border border-violet-300/30 bg-violet-100/70 px-1.5 py-0.5 text-[9px] font-bold text-violet-900">学習専用</span>}{book.canEdit===false && <span className="rounded-full bg-violet-300/12 px-1.5 py-0.5 text-[9px] font-bold text-violet-200">編集不可</span>}{index===0 && <span className="rounded-full bg-cyan-300/12 px-1.5 py-0.5 text-[9px] font-bold text-cyan-200">PINNED</span>}</div><p className="mt-1 text-xs text-slate-400">{book.count}語・{book.scope}</p>{progress && <div className="mt-2"><div className="flex justify-between text-[10px] text-slate-400"><span>達成率 {progress.progressPercent}%</span><span>正答率 {progress.accuracyPercent}%・{progress.studiedWordCount}/{progress.wordCount}語</span></div><div className="mt-1 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-cyan-300 to-violet-300" style={{ width: `${progress.progressPercent}%` }} /></div></div>}</div><ChevronDown className="h-4 w-4 -rotate-90 text-slate-500" /></button> }):<p className="rounded-2xl border border-dashed border-white/15 bg-white/[.025] p-4 text-xs leading-5 text-slate-400">まだ単語帳がありません。右上の「新規作成」から、保存する単語帳を作成してください。</p>}</div>
    {creating && <Modal title="マイ単語帳を作成" onClose={() => setCreating(false)}><p className="text-sm text-slate-300">{subject === "漢字" ? "その他" : subject}用の単語帳名を入力してください。作成後、単語の追加とCSV取込が利用できます。</p><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="例：夏休みの復習" className="mt-4 w-full rounded-xl border border-white/12 bg-slate-950/40 px-3 py-3 text-sm" /><button disabled={createRemote.isPending} onClick={()=>void createBook()} className="mt-4 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{createRemote.isPending?"保存しています…":"作成する"}</button></Modal>}
    {selected && <BookDetail book={selected} subject={subject} setBooks={setBooks} onPractice={() => { setSelected(null); setPage("cards"); }} onClose={() => setSelected(null)} />}
  </div>;
}

function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/70 p-4 sm:place-items-center"><motion.section initial={{ opacity:0, y:20 }} animate={{ opacity:1,y:0 }} className="glass-card w-full max-w-md rounded-[28px] p-5"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">{title}</h2><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8"><X className="h-4 w-4" /></button></div>{children}</motion.section></div> }

export function BookDetail({ book, subject, setBooks, onPractice, onClose }: { book: Book; subject: Subject; setBooks: React.Dispatch<React.SetStateAction<Record<Subject, Book[]>>>; onPractice: () => void; onClose: () => void }) {
  const [front,setFront]=useState(""); const [back,setBack]=useState(""); const [query,setQuery]=useState(""); const [editing,setEditing]=useState<number | null>(null);
  const utils=trpc.useUtils(); const addWord=trpc.wordbooks.addWord.useMutation(); const updateWord=trpc.wordbooks.updateWord.useMutation(); const deleteWord=trpc.wordbooks.deleteWord.useMutation(); const deleteBook=trpc.wordbooks.delete.useMutation();
  // 学習者用の単語帳画面は「自分の教材」だけを編集対象にする。
  // 管理教材は管理画面側でのみ編集するため、管理セッションが残っていても
  // 教室公開・全体公開の教材に編集UIを出さない。
  const editable = book.scope === "自分の教材" && book.canEdit !== false;
  const refresh = async () => { await utils.wordbooks.list.invalidate(); };
  const save = async () => { if (!front.trim() || !back.trim()) return toast.error("表面と裏面を入力してください。"); try { if(book.remoteId){ const current=editing===null?undefined:book.words[editing]; if(current?.id) await updateWord.mutateAsync({vocabularyWordId:current.id,front:front.trim(),back:back.trim()}); else await addWord.mutateAsync({wordbookId:book.remoteId,front:front.trim(),back:back.trim(),source:"manual"}); await refresh(); toast.success(editing===null?"単語を保存しました。":"単語を更新しました。"); }else{ setBooks(current => ({...current, [subject]: current[subject].map(item => { if(item.id!==book.id)return item; const words=saveStudyWord(item.words,{front:front.trim(),back:back.trim()},editing); return {...item,words,count:words.length}; })})); toast.success(editing===null?"単語を追加しました。":"単語を更新しました。"); } setFront("");setBack("");setEditing(null); } catch(error) { toast.error(error instanceof Error?error.message:"単語を保存できませんでした。"); } };
  const edit=(word:Word,index:number)=>{setFront(word.front);setBack(word.back);setEditing(index);}; const remove=async(index:number)=>{try{const word=book.words[index];if(book.remoteId&&word?.id){await deleteWord.mutateAsync({vocabularyWordId:word.id});await refresh();}else setBooks(current=>({...current,[subject]:current[subject].map(item=>item.id===book.id?{...item,words:deleteStudyWord(item.words,index),count:Math.max(0,item.count-1)}:item)}));toast.success("単語を削除しました。");}catch(error){toast.error(error instanceof Error?error.message:"単語を削除できませんでした。");}}; const removeBook=async()=>{if(!book.remoteId || !editable) return; if(!window.confirm(`「${book.name}」を削除しますか？`)) return; try { await deleteBook.mutateAsync({ wordbookId: book.remoteId }); await utils.wordbooks.list.invalidate(); onClose(); toast.success("単語帳を削除しました。"); } catch(error) { toast.error(error instanceof Error ? error.message : "単語帳を削除できませんでした。"); }};
  const filtered=searchStudyWords(book.words,query); const pending=addWord.isPending||updateWord.isPending||deleteWord.isPending||deleteBook.isPending;
  return <Modal title={book.name} onClose={onClose}><p className="text-xs text-slate-400">{book.scope}・{book.words.length}語を表示</p>{!editable && <div className="mt-3 rounded-xl border border-violet-200/25 bg-violet-300/10 p-3 text-xs leading-5 text-violet-100">この単語帳は管理画面で作成された教室教材です。利用者は編集・単語追加・削除・CSV取込を行えません。練習・テスト用の教材として利用できます。</div>}<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="単語を検索" className="mt-3 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/><div className="mt-3 max-h-44 space-y-2 overflow-y-auto pr-1">{filtered.length ? filtered.map(({word,index})=><div key={`${word.id??word.front}-${index}`} className="flex items-center gap-2 rounded-xl bg-slate-950/30 px-3 py-2.5"><span className="min-w-0 flex-1 truncate text-sm font-semibold">{word.front}</span><span className="max-w-[35%] truncate text-sm text-slate-300">{word.back}</span>{subject === "英単語" && <button onClick={() => window.speechSynthesis?.speak(new SpeechSynthesisUtterance(word.front))} className="text-cyan-200"><Volume2 className="h-4 w-4" /></button>}{editable && <><button onClick={()=>edit(word,index)} disabled={pending} aria-label="単語を編集" className="text-violet-200 disabled:opacity-50"><Settings2 className="h-3.5 w-3.5" /></button><button onClick={()=>void remove(index)} disabled={pending} aria-label="単語を削除" className="text-red-200 disabled:opacity-50"><X className="h-3.5 w-3.5" /></button></>}</div>) : <p className="rounded-xl bg-white/5 p-3 text-xs text-slate-400">一致する単語がありません。</p>}</div>{editable && <><div className="mt-4 grid grid-cols-2 gap-2"><input value={front} onChange={e=>setFront(e.target.value)} placeholder={subject==="英単語"?"英単語":"漢字"} className="rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/><input value={back} onChange={e=>setBack(e.target.value)} placeholder={subject==="英単語"?"意味":"読み"} className="rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/></div><button disabled={pending} onClick={()=>void save()} className="mt-2 w-full rounded-xl border border-cyan-200/25 py-2.5 text-xs font-bold text-cyan-200 disabled:opacity-60">{pending?"保存しています…":editing===null?"単語を追加":"単語を更新"}</button>{editing!==null&&<button onClick={()=>{setEditing(null);setFront("");setBack("");}} className="mt-2 w-full text-xs text-slate-400">編集を取り消す</button>}{book.remoteId?<CsvWordImporter wordbookId={book.remoteId} onComplete={async()=>{await refresh();onClose();}}/>:<p className="mt-4 rounded-xl bg-white/5 p-3 text-xs leading-5 text-slate-400">CSV取込は、保存済みの単語帳で利用できます。</p>}</>}<button onClick={onPractice} className="mt-3 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">この単語帳で練習する <ArrowRight className="inline h-4 w-4" /></button>{editable && <button onClick={() => void removeBook()} disabled={pending} className="mt-2 w-full rounded-xl border border-red-200/30 py-2.5 text-xs font-bold text-red-700 disabled:opacity-50">単語帳を削除</button>}</Modal>;
}

export function KanjiCanvasTest({ word, index, total, onAdvance, onExit, isSaving }: { word: Word; index: number; total: number; onAdvance: (correct: boolean) => Promise<void>; onExit: () => void; isSaving: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null); const paths = useRef<{ x: number; y: number }[][]>([]); const activePath = useRef<{ x: number; y: number }[] | null>(null); const [checked,setChecked]=useState(false); const [,render]=useState(0);
  const point = (event: React.PointerEvent<HTMLCanvasElement>) => { const rect=event.currentTarget.getBoundingClientRect(); return {x:(event.clientX-rect.left)*(event.currentTarget.width/rect.width),y:(event.clientY-rect.top)*(event.currentTarget.height/rect.height)}; };
  const redraw = () => { const canvas=canvasRef.current; if(!canvas)return; const context=canvas.getContext("2d");if(!context)return;context.clearRect(0,0,canvas.width,canvas.height);context.strokeStyle="#092344";context.lineWidth=7;context.lineCap="round";context.lineJoin="round";paths.current.forEach(path=>{context.beginPath();path.forEach((item,i)=>i?context.lineTo(item.x,item.y):context.moveTo(item.x,item.y));context.stroke();}); };
  const start=(event:React.PointerEvent<HTMLCanvasElement>)=>{event.currentTarget.setPointerCapture(event.pointerId);activePath.current=[point(event)];paths.current.push(activePath.current);redraw();};
  const move=(event:React.PointerEvent<HTMLCanvasElement>)=>{if(!activePath.current)return;activePath.current.push(point(event));redraw();};
  const finish=()=>{if(activePath.current?.length===1){activePath.current.push({...activePath.current[0],x:activePath.current[0].x+1});redraw();}activePath.current=null;render(value=>value+1);};
  const undo=()=>{paths.current.pop();redraw();render(value=>value+1);}; const clear=()=>{paths.current=[];redraw();render(value=>value+1);};
  return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><div><p className="eyebrow">kanji test · {index+1} / {total}</p><p className="mt-1 text-sm text-slate-300">読みから漢字を書いて回答</p></div><button onClick={onExit} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><section className="glass-card rounded-[30px] p-5"><p className="text-xs text-slate-400">次の読みの漢字を書いてください</p><h1 className="mt-6 text-center text-4xl font-extrabold tracking-[.2em]">{word.back}</h1><div className="mt-7 overflow-hidden rounded-2xl bg-white p-2"><canvas ref={canvasRef} width={620} height={330} onPointerDown={start} onPointerMove={move} onPointerUp={finish} onPointerCancel={finish} className="h-52 w-full touch-none select-none rounded-xl bg-[linear-gradient(rgba(56,106,156,.13)_1px,transparent_1px),linear-gradient(90deg,rgba(56,106,156,.13)_1px,transparent_1px)] bg-[size:32px_32px]" aria-label="漢字を書いて回答するキャンバス" /></div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={undo} disabled={isSaving} className="rounded-xl border border-white/14 py-2.5 text-xs font-bold text-slate-200 disabled:opacity-50"><RotateCcw className="mr-1 inline h-3.5 w-3.5" />一画前に戻る</button><button onClick={clear} disabled={isSaving} className="rounded-xl border border-white/14 py-2.5 text-xs font-bold text-slate-200 disabled:opacity-50">全消去</button></div>{!checked?<button onClick={()=>setChecked(true)} disabled={isSaving} className="mt-3 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">答えを確認する</button>:<div className="mt-4 rounded-2xl bg-cyan-300/10 p-3"><p className="text-xs text-cyan-100">正解の漢字</p><p className="mt-1 text-2xl font-extrabold text-white">{word.front}</p><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={()=>void onAdvance(false)} disabled={isSaving} className="rounded-xl border border-violet-200/25 py-2.5 text-xs font-bold text-violet-100 disabled:opacity-50">{isSaving?"保存中…":"書き直す"}</button><button onClick={()=>void onAdvance(true)} disabled={isSaving} className="rounded-xl bg-cyan-300 py-2.5 text-xs font-bold text-slate-950 disabled:opacity-60">{isSaving?"保存中…":"次の問題"}</button></div></div>}</section></div>;
}

export function CardsView({ books }: { books: Record<Subject, Book[]> }) {
  const [mode, setMode] = useState<"choose"|"practice"|"test"|"result">("choose"); const [subject,setSubject]=useState<Subject>("英単語"); const [index,setIndex]=useState(0); const [flipped,setFlipped]=useState(false); const [result,setResult]=useState({known:0,review:0}); const [answer,setAnswer]=useState(""); const [isSaving,setIsSaving]=useState(false); const savingRef=useRef(false);
  const recordAnswer=trpc.learning.recordAnswer.useMutation();
  const words=useMemo(() => books[subject].flatMap(book=>book.words).slice(0,5),[books,subject]); const word=words[index] ?? {front:"準備中",back:"単語帳に単語を追加してください"};
  const choose = (next: "practice"|"test") => { if(!words.length) return toast.error("先に単語帳へ単語を追加してください。"); setMode(next); setIndex(0);setFlipped(false);setResult({known:0,review:0});setAnswer(""); };
  const advance = async (known:boolean) => { if(savingRef.current)return; savingRef.current=true;setIsSaving(true);const recordMode=mode==="practice"?"practice":"test";try{const updated=await saveAnswerAndGetProgress(()=>recordAnswer.mutateAsync({mode:recordMode,isCorrect:known}),index,words.length,known,result.known,result.review);setResult({known:updated.known,review:updated.review});if(updated.completed){setMode("result");toast.success("学習記録を保存しました。");}else{setIndex(updated.nextIndex);setFlipped(false);setAnswer("");}}catch(error){toast.error(error instanceof Error?error.message:"回答記録を保存できませんでした。通信状況を確認して再試行してください。");}finally{savingRef.current=false;setIsSaving(false);}};
  if(mode==="choose") return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">recall station</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">単語カード</h1><p className="mt-2 text-xs leading-5 text-slate-400">カードをめくり、覚えた感覚を記録します。テストは回答後に結果を表示します。</p><div className="mt-5 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語","漢字"] as Subject[]).map(item=><button key={item} onClick={()=>setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold ${item===subject?"bg-white text-slate-950":"text-slate-400"}`}>{item === "漢字" ? "その他" : item}</button>)}</div></section><section className="glass-card rounded-[26px] p-4"><p className="text-sm font-bold">今日のAIセレクト10</p><p className="mt-1 text-xs text-slate-400">教室の公開教材から {subject === "漢字" ? "その他" : subject} を出題します。</p><div className="mt-4 grid grid-cols-2 gap-2"><button onClick={()=>choose("practice")} className="rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">練習 <BookOpen className="ml-1 inline h-4 w-4" /></button><button onClick={()=>choose("test")} className="rounded-xl border border-white/15 py-3 text-sm font-bold text-white hover:bg-white/8">テスト <Target className="ml-1 inline h-4 w-4" /></button></div></section><section className="rounded-[26px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">カードセットを作成</p><p className="mt-1 text-xs leading-5 text-slate-400">単語帳の範囲を指定し、用途ごとに自分だけのカードセットを作成できます。</p><button onClick={()=>toast.info("カードセット作成は、単語帳の編集画面から順次利用できます。")} className="mt-3 text-xs font-bold text-violet-200">セットを追加 <Plus className="inline h-3.5 w-3.5" /></button></section></div>;
  if(mode==="result") return <div className="px-4 pb-28 pt-8"><section className="glass-card rounded-[30px] p-6 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-amber-300/13 text-amber-200"><Trophy className="h-8 w-8" /></div><p className="eyebrow mt-5">session complete</p><h1 className="mt-2 text-2xl font-extrabold">学習を記録しました</h1><p className="mt-3 text-sm text-slate-300">覚えた：<b className="text-cyan-200">{result.known}</b>　復習：<b className="text-violet-200">{result.review}</b></p><div className="mt-6 grid grid-cols-2 gap-2"><button onClick={()=>setMode("choose")} className="rounded-xl border border-white/15 py-3 text-sm font-bold">一覧へ戻る</button><button onClick={()=>choose("practice")} className="rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">もう一度練習</button></div></section></div>;
  if(mode==="test" && subject === "漢字") return <KanjiCanvasTest word={word} index={index} total={words.length} onAdvance={advance} onExit={()=>setMode("choose")} isSaving={isSaving}/>;
  if(mode==="test") return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><p className="eyebrow">test · {index+1} / {words.length}</p><button onClick={()=>setMode("choose")} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><section className="glass-card rounded-[30px] p-5"><p className="text-xs text-slate-400">次の語の意味を入力してください</p><h1 className="mt-8 text-center text-4xl font-extrabold tracking-[-.04em]">{word.front}</h1><input value={answer} disabled={isSaving} onChange={e=>setAnswer(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!isSaving)void advance(answer.trim()===word.back)}} placeholder="回答を入力" className="mt-10 w-full rounded-2xl border border-white/14 bg-slate-950/35 px-4 py-4 text-center text-lg disabled:opacity-60"/><button onClick={()=>void advance(answer.trim()===word.back)} disabled={isSaving} className="mt-3 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">{isSaving?"記録を保存しています…":"答えを確認する"}</button><p className="mt-3 text-center text-[11px] text-slate-500">正解：{word.back}　（学習用の即時確認）</p></section></div>;
  return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><div><p className="eyebrow">practice · {index+1} / {words.length}</p><p className="mt-1 text-sm text-slate-300">タップで裏面を表示・左右へスワイプして回答</p></div><button onClick={()=>setMode("choose")} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><div className="relative mx-auto h-[370px] max-w-md"><div className="absolute inset-x-6 top-5 h-[340px] rounded-[28px] bg-white/15"/><div className="absolute inset-x-3 top-2 h-[345px] rounded-[28px] bg-white/35"/><motion.button whileTap={{scale:.985}} drag={isSaving?false:"x"} dragConstraints={{ left: 0, right: 0 }} dragElastic={.18} onDragEnd={(_, info) => { if(isSaving)return; const outcome=getSwipeOutcome(info.offset.x); if(outcome==="known")void advance(true);if(outcome==="review")void advance(false); }} onClick={()=>!isSaving&&setFlipped(!flipped)} className="absolute inset-x-0 top-0 flex h-[350px] w-full flex-col justify-between rounded-[28px] bg-[#fbfcff] p-6 text-left text-slate-950 shadow-[0_24px_48px_rgba(0,0,0,.3)] disabled:cursor-wait"><div className="flex justify-between text-[10px] font-bold uppercase tracking-widest text-slate-400"><span>{subject}</span><span>{flipped?"answer":"question"}</span></div><div className="text-center"><motion.p key={flipped?"back":"front"} initial={{opacity:0,y:5}} animate={{opacity:1,y:0}} className="text-4xl font-extrabold tracking-[-.05em]">{flipped?word.back:word.front}</motion.p>{flipped && subject==="英単語" && <button onClick={(e)=>{e.stopPropagation();window.speechSynthesis?.speak(new SpeechSynthesisUtterance(word.front))}} className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-cyan-700"><Volume2 className="h-4 w-4" />発音を聞く</button>}</div><p className="text-center text-xs text-slate-400">{isSaving?"記録を保存しています…":`カードをタップして${flipped?"表面へ":"裏返す"}`}</p></motion.button></div><div className="mx-auto mt-3 grid max-w-md grid-cols-2 gap-3"><button onClick={()=>void advance(false)} disabled={isSaving} className="rounded-xl border border-violet-200/25 bg-violet-400/10 py-3.5 text-sm font-bold text-violet-100 active:scale-[.97] disabled:opacity-50"><RotateCcw className="mr-1 inline h-4 w-4" />まだ覚えていない</button><button onClick={()=>void advance(true)} disabled={isSaving} className="rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 active:scale-[.97] disabled:opacity-60"><Check className="mr-1 inline h-4 w-4" />覚えた</button></div></div>;
}

function AdminView() { const [tab,setTab]=useState("教室"); const tabs=["教室","利用者","単語帳","おすすめテスト","お知らせ","カレンダー"]; return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">classroom control</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">管理画面</h1><p className="mt-2 text-xs leading-5 text-slate-400">対象教室に配信する教材・予定・お知らせをまとめて管理します。</p></section><div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(item=><button key={item} onClick={()=>setTab(item)} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold transition ${tab===item?"bg-cyan-300 text-slate-950":"border border-white/12 bg-white/5 text-slate-300"}`}>{item}</button>)}</div><section className="glass-card rounded-[26px] p-4"><div className="flex items-start justify-between"><div><p className="text-sm font-bold">{tab}</p><p className="mt-1 text-xs text-slate-400">STAR-2026 · 自教室の管理対象</p></div><button onClick={()=>toast.success(`${tab}の作成フォームを開きました。`)} className="rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950"><Plus className="mr-1 inline h-3.5 w-3.5" />追加</button></div><div className="mt-5 rounded-2xl bg-slate-950/30 p-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5" /></div><div><p className="text-sm font-bold">対象教室を確認</p><p className="mt-1 text-xs text-slate-400">教材・お知らせ・イベントは対象教室を指定して配信します。</p></div></div><div className="mt-4 grid grid-cols-2 gap-2">{[["現在配信中","03件"],["下書き","01件"]].map(([label,value])=><div key={label} className="rounded-xl bg-white/5 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-lg font-bold">{value}</p></div>)}</div></div><button onClick={()=>toast.info("先生は担当教室だけを対象に管理できます。全体管理者はすべての教室または個別の教室を選択できます。")} className="mt-4 text-xs font-bold text-cyan-200">権限の説明を見る <ArrowRight className="inline h-3.5 w-3.5" /></button></section><section className="rounded-[24px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">モンスター管理</p><p className="mt-1 text-xs leading-5 text-slate-400">成長段階ごとの画像は外部ストレージに登録し、URLとメタデータのみを保存します。</p><button onClick={()=>toast.info("画像登録はストレージ連携の設定後に有効になります。")} className="mt-3 text-xs font-bold text-violet-200">画像を管理 <ArrowRight className="inline h-3.5 w-3.5" /></button></section></div> }

function PinReissuePanel() {
  const members=trpc.classroom.members.list.useQuery(undefined,{retry:false}); const reset=trpc.classroom.members.resetPin.useMutation(); const [profileId,setProfileId]=useState(""); const [pin,setPin]=useState("");
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!profileId)return toast.error("再発行する利用者を選択してください。");if(!/^\d{4}$/.test(pin))return toast.error("PINは4桁の数字で入力してください。");try{await reset.mutateAsync({profileId:Number(profileId),pin});setPin("");toast.success("PINを再発行し、既存のログインを失効しました。");}catch(error){toast.error(error instanceof Error?error.message:"PINを再発行できませんでした。");}};
  if(members.isLoading)return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">PIN再発行の対象を読み込んでいます…</p></section>;
  if(members.isError)return <section className="rounded-[24px] border border-white/12 bg-white/[.025] p-4"><p className="text-sm font-bold">PINの再発行</p><p className="mt-1 text-xs leading-5 text-slate-400">PINの再発行は、所属教室の先生または教室管理者のみが行えます。</p></section>;
  return <section className="glass-card rounded-[24px] p-4"><p className="text-sm font-bold">PINの再発行</p><p className="mt-1 text-xs leading-5 text-slate-400">再発行すると、対象利用者の既存PINセッションは失効します。新しいPINは安全な経路で共有してください。</p><form onSubmit={submit} className="mt-4 grid gap-2 sm:grid-cols-2"><label className="text-xs font-bold text-slate-200">対象利用者<select value={profileId} onChange={event=>setProfileId(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"><option value="">選択してください</option>{(members.data??[]).map(member=><option key={member.id} value={member.id}>{member.displayName??`利用者 #${member.id}`} · {member.classroomRole}</option>)}</select></label><label className="text-xs font-bold text-slate-200">新しい4桁PIN<input inputMode="numeric" maxLength={4} value={pin} onChange={event=>setPin(event.target.value.replace(/\D/g,""))} placeholder="••••" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-center font-mono text-lg tracking-[.4em]"/></label><button disabled={reset.isPending} className="sm:col-span-2 rounded-xl border border-violet-200/30 bg-violet-300/10 py-3 text-sm font-bold text-violet-100 disabled:opacity-60">{reset.isPending?"再発行しています…":"PINを再発行"}</button></form></section>;
}

function ManagementInsights() {
  const insights=trpc.management.insights.useQuery(undefined,{retry:false,staleTime:30_000});
  if(insights.isLoading)return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">学習・管理記録を集計しています…</p></section>;
  if(insights.isError||!insights.data)return <section className="rounded-[24px] border border-red-200/20 bg-red-400/5 p-4" role="alert"><p className="text-sm font-bold text-red-100">教室の記録を取得できませんでした</p><p className="mt-1 text-xs leading-5 text-slate-300">{insights.error?.message??"通信状況または管理権限を確認して、もう一度お試しください。"}</p><button onClick={()=>void insights.refetch()} disabled={insights.isFetching} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100 disabled:opacity-60">{insights.isFetching?"再取得しています…":"再試行"}</button></section>;
  const data=insights.data; const focusMinutes=Math.floor(data.totalFocusSeconds/60);
  return <section className="glass-card rounded-[26px] p-4"><div className="flex items-center justify-between"><div><p className="eyebrow">record observatory</p><h2 className="mt-1 text-lg font-bold">教室の記録</h2></div><span className="rounded-full bg-cyan-300/10 px-2.5 py-1 text-[10px] font-bold text-cyan-100">実データ</span></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">{[["利用者",`${data.memberCount}人`],["学習時間",`${focusMinutes}分`],["正答率",`${data.retention}%`],["回答数",`${data.answers}問`]].map(([label,value])=><div key={label} className="rounded-2xl bg-slate-950/30 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-lg font-bold">{value}</p></div>)}</div><div className="mt-4"><p className="text-xs font-bold text-slate-200">最近の操作・学習記録</p><div className="mt-2 max-h-44 space-y-2 overflow-y-auto pr-1">{data.recentActivities.length?data.recentActivities.map(item=><div key={item.id} className="rounded-xl bg-white/[.035] px-3 py-2"><p className="text-xs font-semibold text-slate-100">{item.action}</p><p className="mt-1 text-[10px] text-slate-400">{item.classroomName}・{item.actorName} {item.details?`・${item.details}`:""}</p></div>):<p className="rounded-xl bg-white/[.035] p-3 text-xs text-slate-400">まだ記録がありません。教室作成、PIN参加、集中完了などの操作がここに残ります。</p>}</div></div></section>;
}

function WordbookCreationPolicyPanel() {
  const policy = trpc.siteAdmin.wordbookCreationPolicy.useQuery(undefined, { retry: false, staleTime: 15_000 });
  const update = trpc.siteAdmin.setWordbookCreationDisabled.useMutation();
  const utils = trpc.useUtils();
  const disabled = policy.data?.disabled === true;
  const toggle = async () => { try { await update.mutateAsync({ disabled: !disabled }); await utils.siteAdmin.wordbookCreationPolicy.invalidate(); toast.success(!disabled ? "利用者の単語帳新規作成を停止しました。" : "利用者の単語帳新規作成を再開しました。"); } catch (error) { toast.error(error instanceof Error ? error.message : "単語帳作成設定を変更できませんでした。"); } };
  return <section className="glass-card rounded-[26px] border border-amber-200/20 p-4"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow">learner permissions</p><h2 className="mt-1 text-lg font-bold">利用者の単語帳新規作成</h2><p className="mt-2 text-xs leading-5 text-slate-400">停止中は利用者画面の「新規作成」が灰色になり、押せなくなります。既存の単語帳・学習機能は利用できます。</p></div><button type="button" role="switch" aria-label="利用者の単語帳新規作成を停止" aria-checked={disabled} disabled={policy.isLoading || update.isPending} onClick={() => void toggle()} className={`shrink-0 rounded-full px-3 py-2 text-[10px] font-bold transition ${disabled ? "bg-slate-400 text-white grayscale" : "bg-cyan-300 text-slate-950"}`}>{disabled ? "停止中" : "許可中"}</button></div></section>;
}

function PersonalUseCodesPanel() {
  const utils = trpc.useUtils();
  const codes = trpc.siteAdmin.personalClassroomCodes.list.useQuery(undefined, { retry: false });
  const add = trpc.siteAdmin.personalClassroomCodes.add.useMutation();
  const remove = trpc.siteAdmin.personalClassroomCodes.remove.useMutation();
  const [code, setCode] = useState("");
  const save = async (event: React.FormEvent) => {
    event.preventDefault();
    const normalized = code.trim().toUpperCase();
    if (!/^[A-Z0-9-]{3,32}$/.test(normalized)) return toast.error("コードは英数字とハイフンの3〜32文字で入力してください。");
    try { await add.mutateAsync({ code: normalized }); await codes.refetch(); setCode(""); toast.success("個人利用コードを追加しました。"); }
    catch (error) { toast.error(error instanceof Error ? error.message : "個人利用コードを追加できませんでした。"); }
  };
  const removeCode = async (value: string) => {
    try { await remove.mutateAsync({ code: value }); await utils.siteAdmin.personalClassroomCodes.list.invalidate(); toast.success("個人利用コードを削除しました。"); }
    catch (error) { toast.error(error instanceof Error ? error.message : "個人利用コードを削除できませんでした。"); }
  };
  return <section className="glass-card rounded-[26px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-300/12 text-cyan-200"><KeyRound className="h-5 w-5" /></div><div><p className="eyebrow">personal access</p><h2 className="mt-1 text-lg font-bold">個人利用コード</h2><p className="mt-2 text-xs leading-5 text-slate-400">同じコードを使っても利用者同士で教室・学習記録・オンライン状況を共有しません。先生専用管理画面も作成されません。</p></div></div><form onSubmit={save} className="mt-4 flex gap-2"><input aria-label="個人利用コード" value={code} onChange={event => setCode(event.target.value.toUpperCase())} placeholder="例：PERSONAL-2026" className="min-w-0 flex-1 rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" /><button disabled={add.isPending} className="rounded-xl bg-cyan-300 px-4 py-3 text-xs font-bold text-slate-950 disabled:opacity-60">追加</button></form><div className="mt-4 space-y-2">{codes.isLoading ? <p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">コードを読み込んでいます…</p> : (codes.data ?? []).length ? (codes.data ?? []).map(value => <div key={value} className="flex items-center gap-3 rounded-xl bg-slate-950/30 p-3"><span className="min-w-0 flex-1 font-mono text-sm font-bold text-cyan-100">{value}</span><button type="button" onClick={() => void removeCode(value)} disabled={remove.isPending} className="rounded-lg px-2 py-1 text-xs font-bold text-red-200 disabled:opacity-50">削除</button></div>) : <p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">登録済みの個人利用コードはありません。</p>}</div></section>;
}

function AdminWorkspace({ teacherSession, onAdminAuthenticated, onTeacherAuthenticated, onExit }: { teacherSession: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string } | null; onAdminAuthenticated: () => void; onTeacherAuthenticated: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void; onExit: () => void }) {
  const siteAdmin = trpc.siteAdmin.me.useQuery(undefined, { retry: false, staleTime: 30_000 });
  if (!teacherSession && !siteAdmin.data) return <ManagementAccess onClose={onExit} onAdminAuthenticated={onAdminAuthenticated} onTeacherAuthenticated={onTeacherAuthenticated}/>;
  return <><div className="space-y-4 px-4 pt-5"><ManagementInsights/>{teacherSession && <section className="glass-card flex flex-col items-center gap-4 rounded-[26px] p-5 text-center sm:flex-row sm:text-left"><div className="rounded-2xl bg-white p-3 shadow-sm"><QRCodeSVG value={`STUDYVERSE:${teacherSession.classroomCode}`} size={132} level="M" includeMargin={false}/></div><div className="min-w-0"><p className="eyebrow">classroom entry qr</p><h2 className="mt-1 text-lg font-bold">学習者用の入室QRコード</h2><p className="mt-2 text-xs leading-5 text-slate-400">学習者はログイン画面の読み取りボタンから、このQRコードを読み込めます。</p><p className="mt-3 rounded-xl bg-slate-950/30 px-3 py-2 font-mono text-sm font-bold text-cyan-200">{teacherSession.classroomCode}</p></div></section>}</div><LegacyAdminWorkspace teacherSession={teacherSession}/></>;
}

function LegacyAdminWorkspace({ teacherSession }: { teacherSession: { classroomId: number; classroomName: string; classroomCode: string } | null }) {
  const tabs=teacherSession?["利用者","単語帳","おすすめテスト","お知らせ","カレンダー"]:["教室","個人利用","利用者","単語帳","おすすめテスト","お知らせ","カレンダー","モンスター"]; const fields:Record<string,string[]>={"利用者":["表示名","PIN再設定対象","権限"],"単語帳":["単語帳名","科目","対象教室"],"おすすめテスト":["科目","単語帳・範囲","問題数","配信期間"],"お知らせ":["タイトル","本文","対象教室"],"カレンダー":["イベント名","開始日時","終了日時","対象教室"]}; const [tab,setTab]=useState(tabs[0]); const [items,setItems]=useState<Record<string,string[]>>({"利用者":["学習者｜PIN: 再設定可｜student"],"単語帳":["2026 標準単語帳 1｜英語｜対象教室"],"おすすめテスト":["英語｜第1章｜10問｜8/20–8/31"],"お知らせ":["新しい学習ミッション｜本日公開｜対象教室"],"カレンダー":["読解ワークショップ｜8/24 10:00｜8/24 11:00｜対象教室"]}); const [form,setForm]=useState<Record<string,string>>({}); const [editing,setEditing]=useState<number|null>(null); const [roomForm,setRoomForm]=useState({name:"",code:"",teacherUserId:""}); const [editingRoom,setEditingRoom]=useState<number|null>(null); const active=fields[tab] ?? [];
  const utils=trpc.useUtils(); const rooms=trpc.classroom.rooms.list.useQuery(undefined,{retry:false}); const createRoom=trpc.classroom.rooms.create.useMutation(); const updateRoom=trpc.classroom.rooms.update.useMutation(); const deleteRoom=trpc.classroom.rooms.delete.useMutation();
  const reset=()=>{setForm({});setEditing(null);}; const submit=()=>{const values=active.map(field=>form[field]?.trim()??"");if(values.some(value=>!value))return toast.error("すべての必須項目を入力してください。");const item=values.join("｜");setItems(current=>({...current,[tab]:editing===null?[...current[tab],item]:current[tab].map((candidate,index)=>index===editing?item:candidate)}));toast.success(editing===null?`${tab}を追加しました。`:`${tab}を更新しました。`);reset();}; const edit=(item:string,index:number)=>{const values=item.split("｜");setForm(Object.fromEntries(active.map((field,candidate)=>[field,values[candidate]??""])));setEditing(index);}; const resetRoom=()=>{setRoomForm({name:"",code:"",teacherUserId:""});setEditingRoom(null);};
  const submitRoom=async(event:React.FormEvent)=>{event.preventDefault();const name=roomForm.name.trim();const code=roomForm.code.trim().toUpperCase();if(!name)return toast.error("教室名を入力してください。");if(!/^[A-Z0-9-]{3,32}$/.test(code))return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");const teacherUserId=roomForm.teacherUserId.trim()?Number(roomForm.teacherUserId):undefined;if(roomForm.teacherUserId.trim()&&(!Number.isInteger(teacherUserId)||teacherUserId!<=0))return toast.error("担当先生IDは正の整数で入力してください。");try{if(editingRoom===null)await createRoom.mutateAsync({name,code,teacherUserId});else await updateRoom.mutateAsync({classroomId:editingRoom,name,teacherUserId:teacherUserId??null});await utils.classroom.rooms.list.invalidate();toast.success(editingRoom===null?"教室を保存しました。":"教室情報を更新しました。");resetRoom();}catch(error){toast.error(error instanceof Error?error.message:"教室を保存できませんでした。");}}; const removeRoom=async(room:{id:number;name:string;code:string})=>{if(!window.confirm(`「${room.name}（${room.code}）」を削除します。\nこの教室の利用者、教材、学習記録、配信、予定は削除され、元に戻せません。`))return;try{const result=await deleteRoom.mutateAsync({classroomId:room.id});await Promise.all([utils.classroom.rooms.list.invalidate(),utils.wordbooks.managed.invalidate(),utils.classroom.announcements.manage.invalidate(),utils.classroom.recommendedTests.manage.invalidate(),utils.management.insights.invalidate()]);if(editingRoom===room.id)resetRoom();toast.success(`教室を削除しました（利用者${result.deletedMemberCount}人・教材${result.deletedWordbookCount}件）。`);}catch(error){toast.error(error instanceof Error?error.message:"教室を削除できませんでした。");}};
  const header=<><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">classroom control</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">{teacherSession?"先生管理画面":"管理画面"}</h1><p className="mt-2 text-xs leading-5 text-slate-400">{teacherSession?`${teacherSession.classroomName}（${teacherSession.classroomCode}）の利用者・教材・配信だけを管理します。`:"教室に公開する教材・予定・お知らせを、対象を確認しながら管理します。"}</p></section><div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(item=><button key={item} onClick={()=>{setTab(item);reset();resetRoom();}} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold transition ${tab===item?"bg-cyan-300 text-slate-950":"border border-white/12 bg-white/5 text-slate-300"}`}>{item}</button>)}</div></>;
  if(tab==="教室")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<section className="glass-card rounded-[26px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5"/></div><div><p className="text-sm font-bold">教室を保存</p><p className="mt-1 text-xs text-slate-400">作成・編集内容はサーバーへ保存され、次回も表示されます。</p></div></div><div className="mt-5 space-y-2">{rooms.isLoading&&<p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">教室を読み込んでいます…</p>}{rooms.isError&&<p className="rounded-xl bg-red-400/10 p-3 text-xs text-red-100">教室を取得できませんでした。再読み込みしてください。</p>}{(rooms.data??[]).map(room=><div key={room.id} className="flex items-center gap-2 rounded-xl bg-slate-950/30 p-3"><span className="min-w-0 flex-1 text-sm">{room.name}｜{room.code}{room.teacherUserId?`｜先生ID: ${room.teacherUserId}`:""}</span><button onClick={()=>{setEditingRoom(room.id);setRoomForm({name:room.name,code:room.code,teacherUserId:room.teacherUserId?String(room.teacherUserId):""});}} className="text-violet-200" aria-label={`${room.name}を編集`}><Settings2 className="h-4 w-4"/></button><button disabled={deleteRoom.isPending} onClick={()=>void removeRoom(room)} className="rounded-lg px-2 py-1 text-red-200 disabled:opacity-40" aria-label={`${room.name}を削除`}><Trash2 className="h-4 w-4"/></button></div>)}</div><form onSubmit={submitRoom} className="mt-4 grid gap-2 sm:grid-cols-2"><label className="text-xs font-bold text-slate-200">教室名<input required value={roomForm.name} onChange={event=>setRoomForm(current=>({...current,name:event.target.value}))} placeholder="教室名" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label><label className="text-xs font-bold text-slate-200">教室コード<input required disabled={editingRoom!==null} value={roomForm.code} onChange={event=>setRoomForm(current=>({...current,code:event.target.value.toUpperCase()}))} placeholder="例：STAR-2026" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm disabled:opacity-50"/></label><label className="text-xs font-bold text-slate-200 sm:col-span-2">担当先生ID（任意）<input inputMode="numeric" value={roomForm.teacherUserId} onChange={event=>setRoomForm(current=>({...current,teacherUserId:event.target.value.replace(/\D/g,"")}))} placeholder="担当先生ID" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label><button disabled={createRoom.isPending||updateRoom.isPending} className="rounded-xl bg-cyan-300 py-3 text-xs font-bold text-slate-950 disabled:opacity-60">{editingRoom===null?"追加して保存":"更新して保存"}</button><button type="button" onClick={resetRoom} className="rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200">入力を取り消す</button></form></section></div>;
  if(tab==="個人利用")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<PersonalUseCodesPanel/></div>;
  if(tab==="利用者")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<ClassroomMembersPanel/><PinReissuePanel/></div>;
  if(tab==="単語帳")return <div className="space-y-4 px-4 pb-28 pt-5">{header}{!teacherSession && <WordbookCreationPolicyPanel/>}<ClassroomCsvUploader/><ClassroomContentManager section="wordbooks"/></div>;
  if(tab==="おすすめテスト")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<RecommendedTestManager/></div>;
  if(tab==="お知らせ")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<ClassroomContentManager section="announcements"/><AnnouncementHistoryPanel/></div>;
  if(tab==="モンスター")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<MonsterSettingsManager/></div>;
  return <div className="space-y-4 px-4 pb-28 pt-5">{header}<section className="glass-card rounded-[26px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5"/></div><div><p className="text-sm font-bold">{tab}を管理</p><p className="mt-1 text-xs text-slate-400">対象教室を確認して保存します。</p></div></div><div className="mt-5 space-y-2">{items[tab].map((item,index)=><div key={`${item}-${index}`} className="flex items-center gap-2 rounded-xl bg-slate-950/30 p-3"><span className="min-w-0 flex-1 text-sm">{item}</span><button onClick={()=>edit(item,index)} className="text-violet-200" aria-label="編集"><Settings2 className="h-4 w-4"/></button><button onClick={()=>setItems(current=>({...current,[tab]:current[tab].filter((_,candidate)=>candidate!==index)}))} className="text-red-200" aria-label="削除"><X className="h-4 w-4"/></button></div>)}</div><div className="mt-4 grid gap-2 sm:grid-cols-2">{active.map(field=><label key={field} className="text-xs font-bold text-slate-200">{field}<input value={form[field]??""} onChange={event=>setForm(current=>({...current,[field]:event.target.value}))} placeholder={field} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label>)}</div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={submit} className="rounded-xl bg-cyan-300 py-3 text-xs font-bold text-slate-950">{editing===null?"追加して保存":"更新して保存"}</button><button onClick={reset} className="rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200">入力を取り消す</button></div></section>{tab==="利用者"&&<PinReissuePanel/>}<section className="rounded-[24px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">対象教室と権限</p><p className="mt-1 text-xs leading-5 text-slate-400">先生は担当教室だけを対象に配信し、全体管理者はすべての教室または個別の教室を選択できます。サーバー側でも対象範囲を検証します。</p></section></div>;
}

export function ProfileControls({ currentDisplayName, currentAvatarUrl, onDisplayNameSaved, onAvatarSaved, showSmartNotifications = false }: { currentDisplayName?: string; currentAvatarUrl?: string; onDisplayNameSaved?: (displayName: string) => void; onAvatarSaved?: (avatarUrl: string) => void; showSmartNotifications?: boolean } = {}) {
  const utils = trpc.useUtils(); const me = trpc.auth.pinMe.useQuery(undefined, { retry: false, staleTime: 60_000 }); const monster = trpc.monster.dashboard.useQuery(undefined, { retry: false }); const calendar = trpc.calendar.dashboard.useQuery(undefined, { retry: false }); const updateName = trpc.profile.updateName.useMutation(); const uploadAvatar = trpc.profile.uploadAvatar.useMutation(); const [name, setName] = useState(""); const [savedName, setSavedName] = useState(currentDisplayName ?? ""); const [savedAvatarUrl, setSavedAvatarUrl] = useState(currentAvatarUrl ?? "");
  const serverDisplayName = me.data?.profile?.displayName?.trim() || "";
  useEffect(() => { const next = serverDisplayName || currentDisplayName?.trim() || ""; if (next && !name.trim()) { setName(next); setSavedName(next); } }, [serverDisplayName, currentDisplayName, name]);
  useEffect(() => { const next = me.data?.profile?.avatarUrl || currentAvatarUrl || ""; if (next && !savedAvatarUrl) setSavedAvatarUrl(next); }, [me.data?.profile?.avatarUrl, currentAvatarUrl, savedAvatarUrl]);
  const save = async (event: React.FormEvent) => { event.preventDefault(); const nextName = name.trim(); if (!nextName) return toast.error("表示名を入力してください。"); try { await updateName.mutateAsync({ displayName: nextName }); setSavedName(nextName); onDisplayNameSaved?.(nextName); utils.auth.pinMe.setData(undefined, current => current ? { ...current, profile: { ...current.profile, displayName: nextName } } : current); await utils.auth.pinMe.invalidate(); toast.success("表示名を保存しました。ホーム上部にも表示されます。"); } catch (error) { toast.error(error instanceof Error ? error.message : "表示名を保存できませんでした。"); } };
  const selectAvatar = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; if (!["image/png", "image/jpeg", "image/webp"].includes(file.type) || file.size > 3_000_000) return toast.error("3MB以下のPNG・JPEG・WebP画像を選択してください。"); try { const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => typeof reader.result === "string" ? resolve(reader.result) : reject(new Error("画像を読み込めませんでした。")); reader.onerror = () => reject(new Error("画像を読み込めませんでした。")); reader.readAsDataURL(file); }); const result = await uploadAvatar.mutateAsync({ dataUrl }); setSavedAvatarUrl(result.avatarUrl); onAvatarSaved?.(result.avatarUrl); utils.auth.pinMe.setData(undefined, current => current ? { ...current, profile: { ...current.profile, avatarUrl: result.avatarUrl } } : current); await Promise.all([utils.auth.pinMe.invalidate(), utils.classroom.online.list.invalidate()]); toast.success("プロフィール画像を保存しました。"); } catch (error) { toast.error(error instanceof Error ? error.message : "プロフィール画像を保存できませんでした。"); } };
  const eggs = monster.data?.eggs ?? [];
  const eggImageUrl = "/manus-storage/profile-egg-cracked_1d7289e6.png";
  return <div className="mt-5 space-y-4"><section className="rounded-2xl border border-cyan-300/25 bg-cyan-300/10 p-3 text-card-foreground"><div className="flex items-center gap-3"><label className="group relative grid h-16 w-16 shrink-0 cursor-pointer place-items-center overflow-hidden rounded-full border-2 border-cyan-300/40 bg-background text-cyan-700 shadow-sm" aria-label="プロフィール画像を変更">{savedAvatarUrl ? <img src={savedAvatarUrl} alt="プロフィール画像" className="h-full w-full object-cover" /> : <UserRound className="h-7 w-7" />}<span className="absolute inset-0 grid place-items-center bg-slate-950/55 opacity-0 transition group-hover:opacity-100"><ImagePlus className="h-5 w-5 text-white" /></span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={event => void selectAvatar(event)} disabled={uploadAvatar.isPending} className="sr-only" /></label><div className="min-w-0"><p className="text-[10px] font-bold uppercase tracking-[.14em] text-cyan-700 dark:text-cyan-100">ユーザーネーム</p><p data-testid="profile-username" className="mt-1 truncate text-lg font-extrabold text-foreground">{savedName.trim() || me.data?.profile.displayName?.trim() || currentDisplayName?.trim() || "未設定"}</p><p className="mt-1 text-[11px] text-muted-foreground">画像をタップすると変更できます。</p></div></div></section><form onSubmit={save} className="rounded-2xl border border-border bg-card p-3 text-card-foreground"><label className="text-xs font-bold text-foreground">ユーザーネームを変更<input value={name} onChange={event => setName(event.target.value)} placeholder="表示名" className="mt-2 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground placeholder:text-muted-foreground"/></label><button disabled={updateName.isPending} className="mt-2 w-full rounded-xl bg-cyan-300 py-2 text-xs font-bold text-slate-950">名前を保存</button></form>{showSmartNotifications && <SmartNotificationControls/>}</div>;
}

function urlBase64ToUint8Array(value: string) {
  const padding = "=".repeat((4 - value.length % 4) % 4);
  const base64 = (value + padding).replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(base64), char => char.charCodeAt(0));
}

function SmartNotificationControls() {
  const wordbooks = trpc.wordbooks.list.useQuery(undefined, { retry: false, staleTime: 60_000 });
  const settings = trpc.smartNotifications.settings.useQuery(undefined, { retry: false });
  const publicKey = trpc.smartNotifications.publicKey.useQuery(undefined, { retry: false, staleTime: 60_000 });
  const subscribe = trpc.smartNotifications.subscribe.useMutation();
  const save = trpc.smartNotifications.save.useMutation();
  const sendTest = trpc.smartNotifications.sendTest.useMutation();
  const [wordbookId, setWordbookId] = useState(0);
  const [direction, setDirection] = useState<"question" | "answer">("question");
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("21:00");
  const [enabled, setEnabled] = useState(false);
  useEffect(() => { if (settings.data) { setWordbookId(settings.data.wordbookId); setDirection(settings.data.direction); setStartTime(settings.data.startTime ?? "08:00"); setEndTime(settings.data.endTime ?? "21:00"); setEnabled(settings.data.enabled); } }, [settings.data]);
  const persistSettings = (next: { wordbookId?: number; direction?: "question" | "answer"; startTime?: string; endTime?: string; enabled?: boolean }) => {
    const nextWordbookId = next.wordbookId ?? wordbookId;
    if (!nextWordbookId) return;
    void save.mutateAsync({ wordbookId: nextWordbookId, direction: next.direction ?? direction, enabled: next.enabled ?? enabled, startTime: next.startTime ?? startTime, endTime: next.endTime ?? endTime });
  };
  const sendNow = async () => {
    try {
      const result = await sendTest.mutateAsync();
      if (result.sent > 0) toast.success("テスト通知を送信しました。ロック画面を確認してください。");
      else if (result.skipped === "no_subscription") toast.error("端末通知が登録されていません。いったん通知をOFFにしてからONにし、再試行してください。");
      else if (result.skipped === "delivery_failed") toast.error("通知サービスが端末へ届けられませんでした。通知許可を確認してから再試行してください。");
      else if (result.skipped === "disabled") toast.error("スマート通知がOFFです。通知をONにしてから再試行してください。");
      else if (result.skipped === "empty") toast.error("選択した単語帳に単語がありません。単語を追加してから再試行してください。");
      else if (result.skipped === "configuration") toast.error("通知認証の設定に問題があります。管理者へ連絡してください。");
      else toast.error("通知設定が見つかりません。単語帳を選び、通知をONにしてから再試行してください。");
    } catch (error) { toast.error(error instanceof Error ? error.message : "テスト通知を送信できませんでした。"); }
  };
  const toggle = async (next: boolean) => {
    if (!wordbookId) { toast.error("通知する単語帳を選択してください。"); return; }
    try {
      if (next) {
        if (!("serviceWorker" in navigator) || !("PushManager" in window)) throw new Error("この端末のブラウザはプッシュ通知に対応していません。");
        const permission = await Notification.requestPermission();
        if (permission !== "granted") throw new Error("通知が許可されていません。端末の通知設定を確認してください。");
        const registration = await navigator.serviceWorker.register("/sw.js");
        let subscription = await registration.pushManager.getSubscription();
        if (!subscription) subscription = await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(publicKey.data?.publicKey ?? "") });
        const json = subscription.toJSON();
        await subscribe.mutateAsync({ endpoint: subscription.endpoint, keys: json.keys ?? undefined });
      }
      await save.mutateAsync({ wordbookId, direction, startTime, endTime, enabled: next });
      setEnabled(next);
      toast.success(next ? "スマート通知をオンにしました。1時間ごとに届きます。" : "スマート通知をオフにしました。");
    } catch (error) { toast.error(error instanceof Error ? error.message : "通知設定を保存できませんでした。"); }
  };
  return <section className="rounded-2xl border border-border bg-card p-3 text-card-foreground"><div className="flex items-start gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-cyan-300/15 text-cyan-700"><Bell className="h-5 w-5"/></div><div><p className="text-sm font-bold">スマート通知ラーニング</p><p className="mt-1 text-[11px] leading-5 text-muted-foreground">選んだ単語帳から1時間に1問、ロック画面へ通知します。「答えを見る」で答えを確認できます。</p></div></div><label className="mt-4 block text-xs font-bold">通知する単語帳<select aria-label="スマート通知の単語帳" value={wordbookId || ""} onChange={event => { const next = Number(event.target.value); setWordbookId(next); persistSettings({ wordbookId: next }); }} className="mt-2 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground"><option value="">単語帳を選択</option>{(wordbooks.data ?? []).map(book => <option key={book.id} value={book.id}>{book.title}（{book.subject === "kanji" ? "その他" : "英語"}）</option>)}</select></label><label className="mt-3 block text-xs font-bold">通知の出題方向<select aria-label="スマート通知の出題方向" value={direction} onChange={event => { const next = event.target.value as "question" | "answer"; setDirection(next); persistSettings({ direction: next }); }} className="mt-2 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground"><option value="question">問→答（単語を表示）</option><option value="answer">答→問（意味を表示）</option></select></label><div className="mt-3 grid grid-cols-2 gap-2"><label className="text-xs font-bold">開始時刻<input type="time" aria-label="スマート通知の開始時刻" value={startTime} onChange={event => { const next = event.target.value; setStartTime(next); persistSettings({ startTime: next }); }} className="mt-2 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground" /></label><label className="text-xs font-bold">終了時刻<input type="time" aria-label="スマート通知の終了時刻" value={endTime} onChange={event => { const next = event.target.value; setEndTime(next); persistSettings({ endTime: next }); }} className="mt-2 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm text-foreground" /></label></div><p className="mt-2 text-[10px] text-muted-foreground">開始と終了が同じ場合は終日。終了が開始より前の場合は日をまたいで通知します。</p><button type="button" role="switch" aria-label="スマート通知ラーニング" aria-checked={enabled} onClick={() => void toggle(!enabled)} disabled={save.isPending || subscribe.isPending || wordbooks.isLoading || !publicKey.data?.publicKey} className="mt-4 flex w-full items-center justify-between rounded-xl border border-cyan-200/30 bg-cyan-300/10 p-3 text-left text-foreground disabled:opacity-50"><span className="text-xs font-bold">通知を受け取る</span><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${enabled ? "bg-cyan-300 text-slate-950" : "bg-muted text-muted-foreground"}`}>{enabled ? "ON" : "OFF"}</span></button><button type="button" onClick={() => void sendNow()} disabled={!enabled || sendTest.isPending} className="mt-2 w-full rounded-xl border border-violet-300/30 bg-violet-300/10 px-3 py-2.5 text-xs font-bold text-violet-800 disabled:opacity-50">{sendTest.isPending ? "送信しています…" : "今すぐ通知を送る"}</button><p className="mt-2 text-[10px] text-muted-foreground">通知許可が必要です。iPhoneはホーム画面追加後に利用してください。</p></section>;
}

function ProfileSheet({ onClose, onLogout, currentDisplayName, currentAvatarUrl, onDisplayNameSaved, onAvatarSaved }: { onClose: () => void; onLogout: () => void; currentDisplayName?: string; currentAvatarUrl?: string; onDisplayNameSaved: (displayName: string) => void; onAvatarSaved: (avatarUrl: string) => void }) { return <div className="fixed inset-0 z-50 bg-slate-950/45" onClick={onClose}><motion.aside initial={{x:"100%"}} animate={{x:0}} exit={{x:"100%"}} transition={{duration:.22}} onClick={e=>e.stopPropagation()} className="absolute right-0 top-0 h-full w-[min(340px,90vw)] overflow-y-auto border-l border-border bg-background p-5 text-foreground shadow-2xl"><div className="flex justify-between"><div><p className="eyebrow">profile</p><h2 className="mt-1 text-xl font-bold">学習プロフィール</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-muted text-foreground"><X className="h-4 w-4" /></button></div><ProfileControls currentDisplayName={currentDisplayName} currentAvatarUrl={currentAvatarUrl} onDisplayNameSaved={onDisplayNameSaved} onAvatarSaved={onAvatarSaved} showSmartNotifications/><button onClick={onLogout} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl border border-red-200/40 bg-red-400/10 py-3 text-sm font-bold text-red-700"><LogOut className="h-4 w-4" />ログアウト</button></motion.aside></div> }

export default function Home() {
  const preview = new URLSearchParams(window.location.search).get("preview"); const [demoMode,setDemoMode]=useState(false); const [entered,setEntered]=useState(() => ["home","admin"].includes(preview ?? "")); const [authResolved,setAuthResolved]=useState(() => ["home","admin"].includes(preview ?? "")); const [page,setPage]=useState<NavKey>(() => preview === "admin" ? "admin" : "home"); const [profile,setProfile]=useState(false); const [profileDisplayName,setProfileDisplayName]=useState(""); const [profileAvatarUrl,setProfileAvatarUrl]=useState(""); const [books,setBooks]=useState(initialBooks); const [running,setRunning]=useState(false); const [elapsed,setElapsed]=useState(0); const [timerStartedAt,setTimerStartedAt]=useState<Date|null>(null); const [timerSessionId,setTimerSessionId]=useState<string|null>(null); const [timerDurationMinutes,setTimerDurationMinutes]=useState(() => { const value = Number(window.localStorage.getItem("studyverse-timer-minutes")); return Number.isFinite(value) && value >= 5 && value <= 180 ? value : 25; }); const [showTopTimer,setShowTopTimer]=useState(() => window.localStorage.getItem("studyverse-show-top-timer") !== "false"); const [timerFinished,setTimerFinished]=useState(false); const [previousPage,setPreviousPage]=useState<NavKey>("home"); const [teacherView,setTeacherView]=useState<{ id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string } | null>(null); const [reviewLaunch,setReviewLaunch]=useState(false);
  const pinLogin = trpc.auth.pinLogin.useMutation(); const pinLogout = trpc.auth.pinLogout.useMutation(); const siteAdminLogout = trpc.siteAdmin.logout.useMutation(); const teacherAdminLogout = trpc.teacherAdmin.logout.useMutation(); const presencePing = trpc.classroom.online.ping.useMutation(); const pinSession = trpc.auth.pinMe.useQuery(undefined,{retry:false,staleTime:60_000,enabled:!demoMode}); const siteAdminSession = trpc.siteAdmin.me.useQuery(undefined,{retry:false,staleTime:60_000,enabled:!demoMode}); const teacherAdminSession = trpc.teacherAdmin.me.useQuery(undefined,{retry:false,staleTime:60_000,enabled:!demoMode}); const learningSummary=trpc.learning.summary.useQuery(undefined,{retry:false,staleTime:30_000,enabled:!demoMode && !siteAdminSession.data && !teacherAdminSession.data && !teacherView}); const saveFocus=trpc.learning.saveFocusSession.useMutation(); const utils=trpc.useUtils(); const focusSaveInFlight=useRef(false);
  useEffect(()=>{ if(pinSession.data)setEntered(true); },[pinSession.data]);
  useEffect(()=>{ const profile = pinSession.data?.profile; if(!profile) return; setProfileDisplayName(profile.displayName ?? ""); setProfileAvatarUrl(profile.avatarUrl ?? ""); },[pinSession.data?.profile.userId,pinSession.data?.profile.displayName,pinSession.data?.profile.avatarUrl]);
  useEffect(()=>{ if(!entered || demoMode || !pinSession.data?.profile.userId)return; void presencePing.mutateAsync().catch(()=>undefined); const id=window.setInterval(()=>void presencePing.mutateAsync().catch(()=>undefined),30_000); return()=>window.clearInterval(id); },[entered,demoMode,pinSession.data?.profile.userId]);
  useEffect(()=>{ if(siteAdminSession.data){setEntered(true);setPage("admin");} },[siteAdminSession.data]);
  useEffect(()=>{ if(teacherAdminSession.data){setTeacherView(teacherAdminSession.data.teacher);setEntered(true);setPage("admin");} },[teacherAdminSession.data]);
  useEffect(()=>{ if(preview || pinSession.isLoading || siteAdminSession.isLoading || teacherAdminSession.isLoading)return;setAuthResolved(true); },[preview,pinSession.isLoading,siteAdminSession.isLoading,teacherAdminSession.isLoading]);
  useEffect(()=>{ window.localStorage.setItem("studyverse-timer-minutes", String(timerDurationMinutes)); },[timerDurationMinutes]);
  useEffect(()=>{ window.localStorage.setItem("studyverse-show-top-timer", String(showTopTimer)); },[showTopTimer]);
  const pendingFocusKey = "studyverse-pending-focus-session";
  const createFocusSessionId = () => globalThis.crypto?.randomUUID?.() ?? `focus-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const persistFocus = useCallback(async (focusSeconds: number, startedAt: Date, clientSessionId: string, notify = true) => { if (focusSeconds < 1 || focusSaveInFlight.current || demoMode) return false; const pending = { clientSessionId, startedAt: startedAt.toISOString(), focusSeconds }; window.localStorage.setItem(pendingFocusKey, JSON.stringify(pending)); focusSaveInFlight.current = true; try { const result = await saveFocus.mutateAsync({ clientSessionId, startedAt, completedAt: new Date(), focusSeconds }); window.localStorage.removeItem(pendingFocusKey); await Promise.all([utils.learning.summary.invalidate(), utils.learning.trend.invalidate(), utils.learning.dashboard.invalidate(), utils.calendar.dashboard.invalidate(), utils.monster.dashboard.invalidate()]); if (notify) toast.success(result.saved ? `${focusSeconds >= 60 ? `${Math.floor(focusSeconds / 60)}分` : `${focusSeconds}秒`}の集中記録を保存しました。` : "集中記録はすでに保存されています。"); setElapsed(0); setTimerStartedAt(null); return true; } catch (error) { toast.error(error instanceof Error ? `${error.message}。次回の表示時に再送します。` : "集中記録を保存できませんでした。次回の表示時に再送します。"); return false; } finally { focusSaveInFlight.current = false; } }, [demoMode, saveFocus, utils]);
  useEffect(()=>{ if(!pinSession.data?.profile.userId || demoMode) return; const raw=window.localStorage.getItem(pendingFocusKey); if(!raw) return; try { const pending=JSON.parse(raw) as { clientSessionId?: string; startedAt?: string; focusSeconds?: number }; const startedAt=pending.startedAt ? new Date(pending.startedAt) : null; const focusSeconds=pending.focusSeconds; if(!pending.clientSessionId || !startedAt || Number.isNaN(startedAt.getTime()) || !Number.isInteger(focusSeconds) || typeof focusSeconds !== "number" || focusSeconds < 1) { window.localStorage.removeItem(pendingFocusKey); return; } void persistFocus(focusSeconds, startedAt, pending.clientSessionId, false); } catch { window.localStorage.removeItem(pendingFocusKey); } },[demoMode,pinSession.data?.profile.userId,persistFocus]);
  useEffect(()=>{ if(!running)return; const durationSeconds=timerDurationMinutes*60; if(elapsed>=durationSeconds){ setRunning(false); const completedAt=new Date(); const clientSessionId=timerSessionId??createFocusSessionId(); setTimerSessionId(null); void persistFocus(durationSeconds,timerStartedAt??new Date(completedAt.getTime()-durationSeconds*1000),clientSessionId,false); playFocusTimerCompletionSound(); setTimerFinished(true); toast.success(`${timerDurationMinutes}分タイマーが終了しました。`); return; } const id=window.setInterval(()=>setElapsed(s=>s+1),1000); return()=>window.clearInterval(id);},[running,elapsed,timerDurationMinutes,timerStartedAt,timerSessionId,persistFocus]);
  const enter=async(pin:string,classroom:string)=>{if(classroom === "0000"){setDemoMode(true);setEntered(true);setPage("home");toast.success("お試しモードを開きました。学習記録は保存されません。");return;}try{let personalClientId = window.localStorage.getItem("studyverse-personal-client-id"); if (!personalClientId) { personalClientId = globalThis.crypto?.randomUUID?.() ?? `personal-${Date.now()}-${Math.random().toString(36).slice(2)}`; window.localStorage.setItem("studyverse-personal-client-id", personalClientId); } const session=await pinLogin.mutateAsync({pin,classroomCode:classroom,personalClientId});utils.auth.pinMe.setData(undefined,{profile:session.profile,classroom:session.classroom});await utils.auth.pinMe.invalidate();setEntered(true);toast.success("学習空間を開きました。");}catch(error){toast.error(error instanceof Error?error.message:"認証できませんでした。もう一度お試しください。");throw error;}};
  const preloadAiSelect=useCallback(()=>{void utils.wordbooks.list.prefetch({subject:"english"},{staleTime:5*60_000});void utils.wordbooks.list.prefetch({subject:"kanji"},{staleTime:5*60_000});},[utils]); const move=(next:NavKey)=>{if(isPersonalUse && (next === "admin" || next === "online")) return; if(next!==page){setPreviousPage(page);setPage(next);}}; const leaveManagement=async()=>{await Promise.allSettled([siteAdminLogout.mutateAsync(),teacherAdminLogout.mutateAsync()]); setTeacherView(null); setEntered(false); setPage("home"); await Promise.all([utils.siteAdmin.me.invalidate(),utils.teacherAdmin.me.invalidate(),utils.auth.pinMe.invalidate()]);}; const toggleTimer=()=>{if(!running){setTimerFinished(false);setTimerStartedAt(new Date(Date.now()-elapsed*1000));setTimerSessionId(current=>current??createFocusSessionId());setRunning(true);return;}setRunning(false);if(elapsed<1)return;const clientSessionId=timerSessionId??createFocusSessionId();setTimerSessionId(null);void persistFocus(elapsed,timerStartedAt??new Date(Date.now()-elapsed*1000),clientSessionId);}; const topTimerVisible=running&&showTopTimer; const setDuration=(minutes:number)=>{if(running)return;setTimerDurationMinutes(minutes);setElapsed(0);setTimerStartedAt(null);setTimerSessionId(null);};
  if(demoMode)return <DemoMode onLogout={()=>{setDemoMode(false);setEntered(false);setPage("home");toast.info("お試しモードを終了しました。");}}/>; if(!entered&&!authResolved)return <main className="sky-shell grid min-h-screen place-items-center px-5"><section className="glass-card w-full max-w-sm rounded-[28px] p-6 text-center"><p className="eyebrow">restoring session</p><h1 className="mt-2 text-xl font-bold">ログイン状態を確認しています</h1><p className="mt-2 text-sm text-slate-400">前回の学習・管理画面を安全に復元しています。</p></section></main>;
  if(!entered)return <LoginGate onEnter={enter} onAdminEnter={()=>{setTeacherView(null);setEntered(true);setPage("admin");}} onTeacherEnter={teacher=>{setTeacherView(teacher);setEntered(true);setPage("admin");}}/>;
  const activeTeacher = teacherAdminSession.data?.teacher ?? teacherView;
  const isPersonalUse = pinSession.data?.classroom.name === "個人利用";
  const title:Record<NavKey,string>={home:"StudyVerse",books:"単語帳",cards:"単語カード",admin:activeTeacher?"先生管理画面":"管理画面",aiSelect:"AI セレクト 10",online:"オンライン状況"};
  return <div className="sky-shell app-scroll min-h-screen"><div className="star-field opacity-40" /><div className={`relative mx-auto min-h-screen max-w-5xl ${topTimerVisible ? "pt-8" : ""}`}>{topTimerVisible&&<TimerStrip running={running} elapsed={elapsed} durationMinutes={timerDurationMinutes} onToggle={toggleTimer}/>}<Header timerStripVisible={topTimerVisible} page={title[page]} onBack={()=>page==="admin"?void leaveManagement():setPage(previousPage)} onProfile={()=>setProfile(true)} onNavigate={next => move(next)}/><AnimatePresence mode="wait"><motion.main key={page} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-6}} transition={{duration:.18}}>{page==="home"&&<HomeView isPersonalUse={isPersonalUse} setPage={move} onOpenReview={()=>{setReviewLaunch(true);move("cards");}} onPreloadAiSelect={preloadAiSelect} running={running} elapsed={elapsed} timerDurationMinutes={timerDurationMinutes} showTopTimer={showTopTimer} onToggleTimer={toggleTimer} onResetTimer={()=>{setRunning(false);setElapsed(0);setTimerStartedAt(null);setTimerSessionId(null);}} onDurationChange={setDuration} onShowTopTimerChange={setShowTopTimer} summary={learningSummary.data} displayName={pinSession.data?.profile.displayName}/>} {page==="books"&&<BooksView books={books} setBooks={setBooks} setPage={move}/>} {page==="cards"&&<CardsWorkspace books={books} initialReview={reviewLaunch} onReviewOpened={()=>setReviewLaunch(false)} resumeStorageKey={pinSession.data?.profile.userId ? `studyverse-practice-continue:${pinSession.data.profile.userId}` : undefined}/>} {page==="aiSelect"&&<AiSelectWorkspace onBack={() => move("home")}/>} {page==="online"&&<OnlineStatusPage/>} {page==="admin"&&<AdminWorkspace teacherSession={activeTeacher} onAdminAuthenticated={()=>{setTeacherView(null);setPage("admin");}} onTeacherAuthenticated={teacher=>{setTeacherView(teacher);setPage("admin");}} onExit={()=>move("home")}/>}</motion.main></AnimatePresence>{timerFinished&&<div className="fixed inset-0 z-[60] grid place-items-center bg-slate-950/45 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="タイマー終了通知"><section className="w-full max-w-sm rounded-[28px] border border-cyan-200/30 bg-background p-6 text-center text-foreground shadow-2xl"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-cyan-300/20 text-cyan-600"><Volume2 className="h-6 w-6"/></div><h2 className="mt-4 text-xl font-bold">集中タイマーが終了しました</h2><p className="mt-2 text-sm text-muted-foreground">{timerDurationMinutes}分間の集中、おつかれさまでした。</p><button onClick={()=>{setTimerFinished(false);setElapsed(0);setTimerStartedAt(null);setTimerSessionId(null);}} className="mt-5 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">次の学習へ進む</button></section></div>}<nav className="nav-safe fixed inset-x-0 bottom-0 z-30 border-t border-white/[.08] bg-[#080e21]/90 px-3 pt-2 backdrop-blur-xl"><div className="mx-auto grid max-w-lg grid-cols-4">{navItems.filter(item => !(isPersonalUse && item.key === "admin")).map(item=>{const Icon=item.icon;const active=page===item.key;return <button key={item.key} onClick={()=>move(item.key)} className={`relative flex flex-col items-center gap-1 py-2 text-[10px] font-semibold transition ${active?"text-cyan-200":"text-slate-500 hover:text-slate-300"}`}>{active&&<i className="absolute top-0 h-0.5 w-6 rounded-full bg-cyan-200"/>}<Icon className="h-[18px] w-[18px]"/>{item.label}</button>})}</div></nav>{profile&&<ProfileSheet currentDisplayName={profileDisplayName || pinSession.data?.profile.displayName || undefined} currentAvatarUrl={profileAvatarUrl || pinSession.data?.profile.avatarUrl || undefined} onDisplayNameSaved={setProfileDisplayName} onAvatarSaved={setProfileAvatarUrl} onClose={()=>setProfile(false)} onLogout={()=>{void Promise.allSettled([pinLogout.mutateAsync(),siteAdminLogout.mutateAsync(),teacherAdminLogout.mutateAsync()]).finally(()=>{setTeacherView(null);setEntered(false);setProfile(false);setPage("home");toast.info("ログアウトしました。");});}}/>}</div></div>;
}
